/* family-data.js: the Ventional family file. Likes, dislikes, interests and opinions (each opinion is paired with the real computer fact behind it), voices, squabbles, running jokes, bonds, photo-album entries and story threads. Loaded only by the family pages. Invented family, real technology. */
var FAMDATA={"profiles":{"connie":{"l":["Free kilobytes, the unexpected kind, like finding a coin in a coat","Loading things high and watching the MEM /C numbers grow","August 12, and any cake that shares her birthday with the IBM PC","Polishing her gold contacts with a pencil eraser, the way the repair books say","Making room for one more friend, always"],"d":["The words 'Not enough memory'","Static zaps from the living room carpet","Programs that need 590K free and never say so until the last second","A parity check error in the middle of a good game"],"i":["Fitting a whole game under 640K with a few well-placed CONFIG.SYS lines","Recapping old boards one capacitor at a time (the 100 uF ones are her favorites)","Skateboarding the half-pipe and punk rock in the garage","Drawing memory maps on napkins"],"o":[["640K","It was plenty right up until the day it wasn't, and I was there both days.","The 8088 could address 1MB, and IBM set aside 640K for programs and 384K for video, ROM and adapter cards."],["LOADHIGH","Moving a driver upstairs is the nicest thing you can do for a program.","MS-DOS 5.0 (June 1991) added LOADHIGH and DOS=HIGH so drivers could move out of conventional memory on 386 machines."],["MemMaker","A wizard that does what I do, only with two reboots and no personality.","MS-DOS 6.0 (1993) included MemMaker, which rearranged drivers into upper memory and restarted the PC twice."],["Parity chips","Nine chips for eight bits is a bargain, because the ninth one worries for you.","Parity memory stored a ninth bit per byte so the PC could catch a single flipped bit and print PARITY CHECK."],["Windows 95","The walls came down and I am happy for everyone, but I miss the walls a little.","Windows 95 (August 1995) let programs use flat 32-bit memory without anyone juggling drivers inside the first 640K."]],"v":{"s":"Bright, quick and curious, with short sentences, kilobyte numbers and little gasps of delight, and she nearly always ends by making room for whoever she is talking to.","say":["There's always room for one more.","Let me load that high.","Free is a feeling."]},"q":"Reads out a MEM /C report like a weather forecast: 'Largest executable program size, 603K, mostly sunny.'","s":"She keeps one kilobyte permanently empty, just in case a friend needs somewhere to sit.","f":"Losing power, since she knows RAM forgets everything when the plug is pulled, so she keeps a flashlight and writes the important things on paper.","g":[[1981,"Born the day the IBM PC was announced and sure that 640K is the whole world."],[1985,"Emma arrives with a bigger floor plan, and Connie learns that sharing a house is mostly about doors."],[1991,"DOS 5 gives her room to stretch and she finds an empty living room a little spooky."],[2012,"Hosts the museum, still checks her free kilobytes every morning, and teaches visitors to love the small rooms."]]},"emma":{"l":["Page frames drawn in four colors of gel pen","Huge spreadsheets, the kind that scroll for a week","The number 4,294,967,296, the size of a 32-bit address space","The Turbo button, pressed on purpose and with ceremony","Explaining things in numbered lists, preferably on slides"],"d":["People who yawn mid-footnote","Mixing up expanded and extended memory, which are different things","Having four gigabytes of room while DOS only lets her use one small window","A neighbor card parking on her page frame address"],"i":["Memory maps and the arithmetic of segment:offset addresses","Spreadsheet models and counting everything twice","Protected mode and the idea of a room with a lock on the door","Writing a one-page glossary she never finishes"],"o":[["Expanded memory","Sixty-four K at a time through one window is not a flaw, it is a design, and I will draw it for you.","LIM EMS 3.2 (1985) swapped 16K pages of extra RAM into a 64K page frame in the upper memory area."],["Expanded versus extended","They are not the same word and I will say so every single time.","Expanded memory is bank-switched through a page frame, while extended memory sits above 1MB and is reached with the XMS driver HIMEM.SYS."],["The 286","A wonderful chip with one tragic habit: it could not leave protected mode without a reboot.","The 286 had no official way back to real mode, so programs used a keyboard controller reset trick to return."],["EMM386","It lets extended pretend to be expanded, which I find both brilliant and slightly rude.","EMM386.EXE, shipped with DOS 5 (1991), could emulate expanded memory using extended memory on a 386."],["Virtual 8086 mode","The 386 can be many little 8086s at once, which is basically a family.","The 386's virtual 8086 mode let Windows 3.0 Enhanced Mode run several DOS sessions side by side."]],"v":{"s":"Precocious and eager, with long clauses, parenthetical asides and numbered points, and she apologizes for the length mid-explanation and then continues anyway.","say":["Technically...","Let me explain it in four points.","Page frame, singular, sixty-four K."]},"q":"Counts everything twice and announces both totals, then compares them.","s":"She rehearses every explanation on Nibble first, and he has never once interrupted.","f":"A neighbor card taking her page frame address, leaving her room perfectly good and completely unreachable.","g":[[1985,"Born the year of the 386 with all that room and no front door."],[1987,"Expanded memory 4.0 widens her window, and she holds a small assembly about it."],[1993,"A game called Doom climbs straight out of the house with a DOS extender, and she is thrilled and a little jealous."],[2012,"Meets her 64-bit cousins, whose address space is so large that even Emma admits it does not need a footnote."]]},"hiram":{"l":["The view from the loft, especially at sunrise","Telling Dad he can see the roof from up here","His blue cap, worn forward in good weather and backward in great weather","Lowering a basket on a rope for deliveries instead of using the stairs","Room nobody else thought to use"],"d":["The stairs","Being asked to come down for dinner, a talk, or a family photo","Sharing the loft, since only one program can really live up there at a time","Programs that expect addresses to wrap around at one megabyte"],"i":["Tagging everything he can see from the loft with a clipboard","Spotting things through a small telescope in the skylight","Paper airplanes with names and tail numbers","Calling the family from the loft on a very long phone cord"],"o":[["The loft","The rent is nothing, the view is great, and the neighbors are very quiet.","The high memory area is the first 64K above 1MB, exactly 65,520 bytes, reachable from real mode on a 286 or better."],["HIMEM.SYS","The doorman is strict but he knows my name, so we get along.","HIMEM.SYS manages the A20 line and hands out extended memory following the XMS specification of 1988."],["DOS=HIGH","Dad sent the heavy furniture up to me, which is the nicest thing he has ever done.","DOS=HIGH in DOS 5 moves most of the DOS kernel into the high memory area, freeing roughly 40K of conventional memory."],["The A20 line","A tiny wire decides whether I exist, so I say please to it too.","On the 1984 IBM AT the A20 gate was wired through the keyboard controller, which made it slow to switch."],["Coming down","The stairs are a one-way street, and I like the way it points.","The high memory area is the first 64K above the one-megabyte line. Programs could reach it only after HIMEM.SYS switched on the A20 address line, and DOS=HIGH then moved part of DOS up there."]],"v":{"s":"Cheerful kid-brother shout from upstairs, with short punchy sentences, a lot of 'nope', and a habit of trailing off with 'anyway'.","say":["Not coming down.","The view is great from up here.","Ask me nicely. Then ask again."]},"q":"Sends and receives everything by basket on a rope, and labels each delivery with a tiny tag.","s":"He sneaks downstairs once a night to check that Connie's door is shut and to tuck Nibble in.","f":"The A20 gate closing behind him, so that addresses wrap around and the loft quietly stops existing.","g":[[1988,"Born and moves up the very same week, calling it a promotion."],[1991,"DOS=HIGH sends the heavy furniture upstairs and he feels, for the first time, very useful."],[1995,"Windows 95 makes the loft less special and he moves nothing and stays anyway."],[2012,"Grown up, still on the high floor, now with Wi-Fi and a better basket."]]},"ram":{"l":["Page one of the manual, read slowly and in order","The heavy clack of a buckling-spring keyboard on a quiet night shift","A folder of receipts, labeled, with tabs","The hum of a raised-floor computer room at three in the morning","Tube socks pulled up exactly to the line"],"d":["Anyone skipping the manual","Unlabeled cables","Power flickers during the nightly batch run","Being asked to sort his collection, which has not been sorted since 1981"],"i":["Nightly batch jobs finishing on time and in order","Repair journals that log every screw he ever bought","Soldering in the garage, with the door open and the radio low","Recapping old boards, especially the big 1000 uF electrolytics"],"o":[["640K","I said plenty, and in 1981 plenty was correct.","The original IBM PC shipped with 16K to 64K on the motherboard and could take 256K on the board itself, so 640K was far beyond anything installed."],["Manuals","The best-written documents in computing are the ones nobody reads, and they come with schematics.","The IBM PC Technical Reference (1981) included full schematics and the BIOS source listing."],["4.77 MHz","A frugal number: one-third of a crystal that was already in the TV.","The PC's 4.77 MHz clock was the 14.31818 MHz crystal divided by three, four times the NTSC color burst frequency."],["Backups","A good tape reel holds more than any PC will ever need, and I mean that kindly.","A nine-track reel held tens to well over a hundred megabytes depending on density, more than any 1981 PC disk."],["The Model F keyboard","A keyboard should let you hear that you typed.","The 1981 IBM PC keyboard used buckling-spring switches with a distinct tactile click."]],"v":{"s":"Slow, measured and deadpan, with complete sentences, a gentle 'Now,' before every statement, dad-joke puns and numbers recited with their units.","say":["Read the manual first.","Now. Let's not panic.","Plenty. For now."]},"q":"Can produce the receipt for any screw in the house, and the box it came in.","s":"In his file cabinet, the folder 'Reasons I Was Right' is thin and the folder 'Reasons I Am Proud To Have Been Wrong' is thick.","f":"A night-shift power flicker with no UPS and a batch job only half done.","g":[[1952,"Born, and shows an early talent for reading the instructions on the cereal box twice."],[1981,"Buys the family's first PC and declares 640K plenty, to cheers."],[1991,"Reads the DOS 5 manual cover to cover and rearranges the furniture with a straight face."],[2012,"Retires from nights, keeps the hours, and owns a very good thermos."]]},"rhoda":{"l":["A tidy shelf where everything has a labeled place","The little write-protect tab, which she calls a boundary with good manners","Quotations, for every occasion and age","A cup of tea made the same way every day, never adjusted","A story that turns out the same way each time it is told"],"d":["'Write protect error writing drive A. Abort, Retry, Fail?', which she finds a little too dramatic","Anyone trying to patch her rules without asking","Sticky notes on things that should be read, not changed","Surprises during bedtime, which is write-protected"],"i":["Reading, especially reference books with good indexes","Collecting quotations in a small notebook she never lets anyone edit","CD-ROMs, which she considers the first sensible, permanent library","Teaching the kids to ask permission before they edit anything"],"o":[["Rules","A rule that can be changed by anyone is a suggestion with ambition.","Read-only memory keeps its contents without power, and the IBM PC's BIOS and Cassette BASIC lived in ROM chips."],["EPROM stickers","A window in the lid is how you know a chip can change its mind, and the sticker is how you tell it not to.","UV-erasable EPROMs had a quartz window that was usually covered by a label to stop light from erasing them."],["Flash ROM","A read-only rule that can be updated on holidays, with warning, is still a good rule.","By the mid-1990s PC BIOS chips were flash memory, which can be rewritten in place but not by accident."],["CD-ROM","Six hundred and fifty megabytes, and nobody can scribble on it. Marvelous.","A standard CD-ROM held about 650MB and could not be rewritten."],["ATTRIB +R","A single flag, and the house is quiet.","The DOS ATTRIB command sets the read-only file attribute, and DOS refuses to overwrite such files."]],"v":{"s":"Calm, formal and declarative, with a quotation never far behind, and a tone that suggests the matter is already decided and is only being read aloud.","say":["It is written.","You may read it. You may not edit it.","As the saying goes..."]},"q":"Calls bedtime 'write-protected' and enforces it by touching the little tab on her sleeve.","s":"One shelf in her room is marked 'Read-Write' and holds every drawing the kids ever gave her.","f":"A power surge in the middle of a flash update, because even a read-only life needs a minute to be rewritten gently.","g":[[1954,"Born Reed-Only and first to point out that the pun is on purpose."],[1981,"The IBM PC arrives with Cassette BASIC in ROM, and Rhoda moves into a room built for her."],[1995,"BIOS goes flash, and she begrudgingly accepts a careful rewrite on holidays."],[2012,"Keeps the family rules, adds one: you may always ask."]]},"floyd":{"l":["Telling the whole story, in order, with every disk swap","A fresh felt-tip marker for the label, never a ballpoint","A clean write-protect tab, tape or slider, either kind","The comfortable chunk-chunk-whirr of a drive spinning up at 300 RPM","A shirt pocket that fits exactly 360K"],"d":["Fingerprints on the shiny part","Magnets, which are rude and should not be left on the fridge","'Not ready reading drive A. Abort, Retry, Fail?'","Being left in a hot car or a sunny window"],"i":["Swapping disks for installation programs, and remembering which was which","Hangman, which he plays against himself and always loses","Labeling disks in tiny, careful handwriting","Tours, at floppy drive speed"],"o":[["Capacity","Three hundred sixty kilobytes is a lot if you are patient.","A double-sided 5.25-inch floppy with 40 tracks of 9 sectors of 512 bytes holds 368,640 bytes, called 360K."],["Disk 7 of 14","It is always disk 7, and I will not be taking questions.","Large installs in the early 1990s came on piles of disks, and the Windows 95 floppy edition used 13 special 1.68MB disks."],["3.5-inch disks","A hard shell and a sliding door, and I felt invincible, although my insides are still 360K.","3.5-inch disks came in 720K and 1.44MB, with a metal shutter and a sliding write-protect tab."],["The tape trick","A piece of tape over the hole is a family secret and also not a good idea.","Taping over the high-density hole of a 1.44MB disk made it format as 720K, with mixed results."],["Write protect","Cover the notch and nothing changes, which is how I like my days.","A 5.25-inch floppy was write-protected by covering the notch, while 3.5-inch disks used a slider."]],"v":{"s":"Slow, warm and rambling, with 'back in my day' detours, a habit of losing the thread, and a gentle return to the number seven.","say":["Now where was I...","Disk 7. Or was it 8?","Don't bend the cardboard, dear."]},"q":"Counts disks aloud while walking, and starts over whenever interrupted.","s":"He knows exactly where disk 7 is. He keeps losing it on purpose so the family will help him look.","f":"A read error in the middle of the best part of the story.","g":[[1924,"Born, according to family legend, as a folded piece of cardboard with great ambitions."],[1981,"Joins the PC era carrying 160K, then 180K, then 360K, a little prouder each time."],[1987,"Trades the floppy sleeve for a hard shell and a sliding door, declares it the best year yet, and stays 360K at heart."],[2012,"Retires to a cardboard museum case and tells his stories to anyone patient enough."]]},"winnie":{"l":["A spare room, made up and ready for any guest","Baking, especially things that take a long time to cool","Family albums, in order, with captions","Defragmenting the pantry on Sunday afternoons","The low, steady hum of her platters at rest"],"d":["Fragmentation, meaning anything scattered all over the house","Being bumped while she is spinning","Lost clusters, orphaned crumbs and missing things generally","'Sector not found'"],"i":["Family history, with forty megabytes of stories to prove it","Checking the references of every program that wants to move in","Knitting, tangled at first, then very neat","Quiet afternoons, which she says are her true sweet spot"],"o":[["Room to spare","There is always room, dear. Though do wipe your feet.","The 20MB and 40MB hard disks of the mid-1980s felt enormous next to 360K floppies."],["The name Winchester","Named for a rifle, which is silly, but I have always been a lady of adventure.","IBM's 1973 3340 drive held two 30MB spindles and was nicknamed 'Winchester' after the 30-30 rifle."],["The 32MB limit","Forty megabytes in two pieces, like a pie that someone insisted on cutting.","DOS before 4.0 (1988) could not format a partition larger than 32MB, so a 40MB drive needed two drive letters."],["Head parking","A good guest tucks the heads in before leaving.","Hard drives had to park their heads on a landing zone before power-off, and early PCs shipped with a PARK command."],["Defragmenting","Tidying is a form of love, and DEFRAG is the broom.","MS-DOS 6.0 (1993) shipped DEFRAG, which rewrote files into contiguous clusters."]],"v":{"s":"Warm, unhurried and grandmotherly, with 'dear' and 'sweetheart' woven into every second sentence and a tendency to answer a question with a recipe.","say":["There's room, dear.","Let me check your references.","Mind the platters."]},"q":"Interviews every new program at the door and rejects anything with a missing manual.","s":"She has about three megabytes of unlabeled family photos tucked away so nobody will ever find them missing.","f":"A head crash, which she thinks of as a loud and very unkind thing to say to a person.","g":[[1926,"Born, as the family tells it, an idea that waited decades for a platter to live on."],[1983,"The PC XT welcomes her young cousins with 10MB, and she smiles politely."],[1987,"Gets her 40MB and says she will never fill it, which becomes the family catchphrase."],[2012,"Terabyte great-grandchildren visit, and she still does not fill her drawers."]]},"augusta":{"l":["A numbered list, completed in order","@ECHO OFF, which she says is the quiet before the work begins","A PROMPT with the path in it, so you always know where you are","Sunday mornings, which are the same as every other morning and that is the point","Pressing 'any key' and only the right one"],"d":["Installers that quietly add a line to the bottom of her list","'Out of environment space'","Questions before she is done","A misspelled command, which she reads aloud with feeling"],"i":["Writing out the morning routine again, more clearly","The PATH variable, which she keeps pruned and polished","Reading the change log aloud from the top","Labeling the labels"],"o":[["Order","Top to bottom, one line at a time, and no one is hurt.","AUTOEXEC.BAT runs its commands in order, one per line, after CONFIG.SYS has set the machine up."],["REM","A comment is a love letter that the computer politely ignores.","The REM command in a batch file marks a remark that DOS skips."],["Environment space","A house with 256 bytes of shelf is a house with opinions about what goes on it.","The default DOS environment was a small block of memory, and a long PATH could trigger 'Out of environment space.'"],["Press any key","Any key means any key. Please stop looking for the one marked 'Any'.","The PAUSE command prints 'Press any key to continue' and waits for any key."],["SET BLASTER","Sandy's line is the loudest one in my list and the best formatted.","SET BLASTER=A220 I5 D1 told games the Sound Blaster's address, interrupt and DMA channel."]],"v":{"s":"Brisk, orderly and imperative, speaking in numbered steps with no wasted words, and she announces each item as though checking it off.","say":["Item one.","In order, please.","No questions until I am done."]},"q":"Reads her own boot list aloud every morning, loudly, and begins again if anyone speaks.","s":"The last line of her list, which nobody reads, says: 'Have a nice day.'","f":"An installer that rewrites her list without telling her.","g":[[1949,"Born as a very small, very neat to-do list."],[1983,"Moves into the family's boot sequence and takes the second shift."],[1991,"DOS 5 adds LOADHIGH and DOSKEY, and she has a very thorough week."],[2012,"Still runs first thing every morning, now in a museum, now with a nameplate."]]},"conrad":{"l":["A jumper set exactly right, and then checked again","The word 'technically'","A hot mug that stays hot until the end of the sentence","DEVICE=HIMEM.SYS as the first line, because it feels like a good start","A neat DIP switch bank, all in a row"],"d":["'Error in CONFIG.SYS line 7'","A driver that loads before it should","The F5 key, because it skips him","Anyone saying 'it should just work'"],"i":["Tuning CONFIG.SYS, which he has done since 1983 and calls unfinished","IRQ and DMA charts, which he reads in bed","Benchmarks, which are not a competition","Jumpers, only jumpers, forever jumpers"],"o":[["FILES=30","The default of eight is a typo that became a lifestyle.","DOS defaulted to FILES=8, and many programs needed 20 or more."],["Line one","If the first line is wrong, the house never wakes up, and that is entirely my responsibility.","CONFIG.SYS is read first at boot, and a wrong device line can stop a machine from starting."],["Multi-config menus","Finally, a menu for the family's moods.","MS-DOS 6.0 (1993) added multiple boot configurations selectable from a menu in CONFIG.SYS."],["F8","Step by step is how I live anyway.","DOS 6 let you press F8 at boot to confirm each CONFIG.SYS and AUTOEXEC.BAT line and F5 to skip both."],["Jumpers","A small plastic cap that decides your whole afternoon.","ISA cards used jumpers and DIP switches to set IRQ, DMA and I/O addresses, which had to avoid conflicts."]],"v":{"s":"Dry, deadpan and technical, with sighs, hedges and 'technically' as a sentence opener, and a slow release of the answer, usually followed by a second sigh.","say":["Technically... it depends on the jumpers.","If I'm wrong, nothing starts.","I am not sighing. I am venting."]},"q":"Sighs softly before delivering any answer that begins with 'actually'.","s":"He keeps a backup copy of the family's CONFIG.SYS on a disk marked 'Just In Case' and checks it every Sunday.","f":"A typo on line one.","g":[[1947,"Born a short list of settings with a very long sense of responsibility."],[1983,"Settles into the family boot, first in line and last to be thanked."],[1991,"DOS 5 hands him DEVICEHIGH, and he allows himself half a smile."],[2012,"The family moves on to plug and play, and he secretly misses the jumpers."]]},"tess":{"l":["A good hotkey, pressed at exactly the right moment","Being useful: a notepad, a calculator, a pop-up calendar","The hallway, especially the corner by the radiator","Nibbling on stray kilobytes when nobody is looking","Being thanked, which has happened twice"],"d":["Ctrl-Alt-Delete","Other TSRs who hook the same interrupt","Being unloaded in the wrong order","Being called 'the houseguest' to her face"],"i":["Interrupt vectors, which she considers a kind of mailing system","Listening at the keyboard for her cue","Pop-up utilities of all sorts","A small notebook of everyone's birthdays"],"o":[["Staying resident","I only said I'd be a minute. I did not say which minute.","A TSR ends but stays in memory using a DOS call such as INT 21h function 31h, keeping its code alive."],["Hotkeys","I wait, quiet as a cat, until the right two keys, and then I am delightful.","Pop-up TSRs like notepads and calculators hooked the keyboard interrupt and woke up on a hotkey."],["The interrupt table","Two hundred fifty-six little doorbells, and I know every one.","The interrupt vector table holds 256 four-byte entries in the first 1,024 bytes of memory."],["MEM /C","It tells everyone I'm in the hallway, which is not wrong.","The MEM /C command lists every program and TSR in memory and how much each one uses."],["Unloading","Last in, first out, please, like a polite crowd leaving a theater.","TSRs usually had to be removed in the reverse of the order they were loaded."]],"v":{"s":"Soft, whispery and apologetic, with 'just passing through' energy, and a habit of appearing mid-conversation with a very small announcement.","say":["Don't mind me.","Only a minute.","Did someone press my key?"]},"q":"Pops up unannounced when someone presses Ctrl and Alt and then pretends she did not.","s":"She uses her 16K to remember everyone's birthday, and she pops up on the day with a very small card.","f":"Ctrl-Alt-Delete, the tiny red button of the universe.","g":[[1983,"Knocks on the door and promises she will only be a minute."],[1984,"Pop-up utilities make hotkey TSRs famous, and she feels briefly like a star."],[1991,"LOADHIGH offers her a room upstairs, and she politely declines because the hallway is home."],[2012,"Still resident, now with a nameplate on the hallway wall, which she calls a lease."]]},"nibble":{"l":["Sunflower seeds, any kind, always in the cheeks","The wheel in the hallway, run at night","A cardboard tube, preferably one nobody else wants","Hexadecimal digits, because there are exactly sixteen of them","A warm spot near the power supply"],"d":["The vacuum cleaner","A wheel that squeaks","Being counted twice by Emma","Sunlight before dusk"],"i":["Running the wheel, which he believes makes the lights come on","Hoarding seeds and the occasional tiny prize ticket","Digging a very small tunnel under the keyboard","Watching Dad work on the night shift, because they keep the same hours"],"o":[["A nibble","Four bits, sixteen values, one hex digit, and I am exactly the right size.","A nibble is half a byte, four bits, enough for one hexadecimal digit from 0 to F."],["The wheel","I run, and the tickets come out. Obviously.","Hamsters are nocturnal and can run several miles on a wheel in one night."],["Cheeks","Storage is whatever fits in a cheek.","Hamsters carry food in expandable cheek pouches."],["Night shift","Dad and I are the only two who understand the night.","Hamsters are most active at night, which matches Raymond's data center schedule."],["Age","I am considerably older than the pamphlet says.","Pet hamsters usually live about two to three years, which the family politely ignores."]],"v":{"s":"Narrated behavior only: Nibble squeaks, stuffs, scurries and stares, and the narrator interprets him with warm and confident misreadings.","say":["*squeak*","*stuffs a seed, says nothing*","*runs the wheel, looks meaningful*"]},"q":"Keeps bingo balls in his cheeks and will not say which ones.","s":"Every night he tucks one seed under Connie's pillow, for luck.","f":"The vacuum cleaner, and its terrible, friendly roar.","g":[[1982,"Arrives as half a byte and twice the personality."],[1984,"Meets Mat the Mouse and respectfully ignores him."],[1993,"The wheel acquires a number counter, and he believes he is being paid."],[2012,"Remains, by family agreement, the same age as always."]]},"dot":{"l":["Green-bar paper and its neat little stripes","The long, glorious screech of a carriage return","Tractor-feed holes down both edges, in perfect rhythm","Printing a banner with a very large font and a very small message","Triplicate forms, because everyone should get a copy"],"d":["A ribbon that has run dry","A paper jam, which she takes personally","Quiet laser printers, which she says have no soul","A blank page printed by accident"],"i":["ASCII art, especially large and ambitious","Printing the family's labels with proper margins","Print Shop banners, greeting cards and signs","ESC codes, which she learns by heart for fun"],"o":[["Noise","If you can't hear it, did it really print?","Impact printers were loud, producing a buzzing and rasping sound as pins struck the ribbon."],["Near letter quality","Double-strike is just my way of saying I meant it.","Near letter quality mode printed each line twice or in slow passes to make text look sharper."],["Triplicate","Original, copy, copy. Everyone remembers the original.","Impact printers could print through multi-part carbonless forms, which lasers cannot do."],["Print Screen","One key and the whole screen comes out as paper. Marvelous.","Shift-PrtSc on the IBM PC sent the text screen to the printer."],["Green bar","The stripes are not decoration, they are structure.","Green-bar continuous paper had alternating shading to help readers follow long rows of figures."]],"v":{"s":"Bold, theatrical and loud, repeating key lines three times with each repeat a little fainter, like a carbon copy.","say":["BZZZT. (bzzzt.) (bzzt.)","Printing now. (printing.) (printing...)","In triplicate, naturally."]},"q":"Says each important sentence three times, each one lighter than the last.","s":"She prints a very quiet get-well note whenever anyone in the family is sick, and signs it in tiny dots.","f":"The sound of her own ribbon running dry.","g":[[1981,"Born the same year as Connie, and they were friends before either could read."],[1985,"Twenty-four pins arrive and her handwriting finally looks professional."],[1993,"Meets laser printers, shrugs and prints more loudly."],[2012,"Prints for the museum, still in triplicate, still loud."]]},"viv":{"l":["Palette cycling, where the sea moves without anyone redrawing it","The 256-color sunrise screen that every demo seems to include","A clean gradient with no banding","Monitors with a refresh rate that does not flicker","Color, always, and the word 'gorgeous'"],"d":["The magenta, cyan and white palette of CGA, which she calls a bad dream","Flicker, in any refresh rate below 70 Hz","Banding in gradients","Being asked to choose between two colors she loves"],"i":["Mode 13h and its 320 by 200 world","Dithering and the art of looking like more colors","Photography, framed in 256 colors","The design of the VGA connector, which she thinks is underrated"],"o":[["VGA","Sixteen colors on a good day, 256 on a great one, and I dress accordingly.","VGA (1987) offered 16 colors at 640 by 480 or 256 colors at 320 by 200, chosen from a palette of 262,144."],["CGA","Four colors, and three of them are the wrong ones.","CGA (1981) displayed four colors at 320 by 200, most often cyan, magenta, white and black."],["EGA","A teenage phase: sixteen at a time, out of sixty-four.","EGA (1984) showed 16 colors at once from a palette of 64."],["Palette cycling","The cheapest magic trick in graphics.","VGA could shift entries in its color palette without redrawing pixels, animating water and fire."],["Mode X","A tweak that gave us square pixels and a little respect.","Mode X (1990) used VGA's unchained memory to get 320 by 240 with square pixels."]],"v":{"s":"Glamorous, visual and a bit theatrical, calling everyone 'darling', describing the world in color names and hex codes, and treating each room as a composition.","say":["Darling, that is not a color, that is a beige.","Sixteen is a lifestyle.","Frame it, then shoot it."]},"q":"Narrates any scene as though it were a magazine cover, with the lighting.","s":"She keeps one old green-screen phosphor photo of the family on her desk, and she cries a little at it.","f":"A monitor set to 60 Hz in a bright room.","g":[[1987,"Born with 256KB of video memory and more ideas than she could fit."],[1989,"Super VGA arrives and she bargains for 800 by 600 and more colors."],[1995,"Gets high color, 65,536 of them, and calls it 'almost enough'."],[2012,"Millions of colors on every screen, and she still dresses in sixteen for special occasions."]]},"sandy":{"l":["Volume, whatever it is","Wavetable synths, MIDI files and a really good tracker tune","IRQ 5, because it is hers","FM synthesis, which she says sounds like a very friendly robot","A Walkman, tape deck, headphones and a pair of speakers all playing at once"],"d":["The PC speaker, a single square-wave beep","Hanging MIDI notes, which stay on until someone fixes them","Anyone saying 'Can you turn that down?'","Crackle and hiss from other cards on the bus"],"i":["MOD and MIDI music","Setting up sound card jumpers with Conrad, who sighs","Arguing about IRQ 5 with anyone who will argue","Arranging the family's ringtones"],"o":[["IRQ 5","It's mine, it's always been mine, and somebody keeps parking there.","Sound Blaster 16 defaulted to IRQ 5, I/O address 220h and DMA 1, but older XT hard disk controllers also used IRQ 5."],["The BLASTER variable","A little line that tells every game exactly how loud to be.","SET BLASTER=A220 I5 D1 T4 told games the card's address, interrupt, DMA channel and card type."],["AdLib versus Sound Blaster","One does music, the other does music and talks.","AdLib (1987) did FM synthesis only, while the Sound Blaster (1989) added digital sample playback."],["16-bit audio","Stereo, 44.1 kHz, no static. A perfect Tuesday.","The Sound Blaster 16 (1992) added 16-bit, 44.1 kHz stereo sound."],["Joystick port","One port does games and music, and the family says that is a mess. I say that is efficient.","The PC game port doubled as a MIDI port on many sound cards."]],"v":{"s":"Loud, high-energy and playful, with exclamation marks, capital letters for emphasis and musical comparisons, and she shouts to be heard and then keeps shouting for fun.","say":["TURN IT UP!","That's MY IRQ!","I can't hear you. Say it with a drum."]},"q":"Taps out a drum fill on the nearest surface before answering anything.","s":"She listens to quiet piano music late at night when nobody is around.","f":"A stuck MIDI note that rings forever and no one can find the reset.","g":[[1989,"Born the same year as the Sound Blaster, and she argues about her birthday at full volume."],[1992,"The 16-bit upgrade makes her very loud and very clear."],[1995,"Plug and play ends the IRQ fights, and she misses the arguments."],[2012,"Still on IRQ 5 out of loyalty, with the volume where it always was."]]},"mo":{"l":["The first two seconds of silence before the handshake","A clean connect at the full speed she was promised","Long evenings with a good bulletin board","A well-built, patient protocol like ZMODEM that can resume","A quiet house, so she can hear the carrier"],"d":["Call waiting","Someone picking up the extension mid-call","'NO CARRIER'","People who say baud when they mean bits per second"],"i":["Bulletin board systems and the people who run them","AT commands, which she knows by heart","Collecting dial-up numbers, labeled by speed","Listening to line noise and guessing which neighbor is on the phone"],"o":[["The handshake","The screech is not noise, it is two machines being polite.","A modem handshake negotiates speed and error correction using tones, starting with an answer tone around 2100 Hz."],["Speeds","Three hundred, twelve hundred, twenty-four hundred, and each one felt like a miracle.","Common modem speeds went 300, 1200, 2400, then 9600, 14,400, 28,800 and 56,000 bits per second."],["Baud","Two thousand four hundred baud is a family tradition, but it is really six hundred.","A V.22bis 2400 bps modem sent 600 symbols per second at 4 bits per symbol, so it was technically 600 baud."],["AT commands","ATDT and a number is the most romantic sentence in computing.","The Hayes AT command set uses ATDT to tone-dial, ATH to hang up and +++ to escape back to command mode."],["Call waiting","A beep of betrayal in the middle of the upload.","Call waiting tones could drop a modem connection, which is why many people dialed *70 first to disable it."]],"v":{"s":"Patient and slow, speaking in short phrases with pauses and the occasional dial tone, as if each sentence were being negotiated on the line.","say":["ATDT... please hold.","Negotiating...","CONNECT 2400. That is plenty."]},"q":"Hums the handshake tune when nervous, and everyone in the house can name the pitch.","s":"She has a tape of every handshake she has ever heard, labeled by date, and plays them to fall asleep.","f":"A single beep in the middle of a long download.","g":[[1979,"Born at 300 bits per second and counting every one."],[1983,"1200 baud arrives and Mo celebrates with the whole street's phone bill."],[1998,"56K at last. She still hums the handshake."],[2012,"Broadband arrives, and she keeps the handshake as her ringtone."]]},"zack":{"l":["Being folded small and then unfolded somewhere surprising","A bargain for a dollar at a swap meet","Getting everywhere before anyone invited him","Cartridges, disks and anything that can be stacked","Winning, especially before the game starts"],"d":["The click of death","'CRC error' on the very last file","Being called 'just a floppy'","Magnets, the sun and the back seat of a hot car"],"i":["Swap meets, folded small, with a dollar in his pocket","Self-extracting archives, which he considers a magic trick","Speedruns of games he has never played before","Trading disks at the bus stop"],"o":[["Being zipped","Fold small, travel light, unfold on the couch. It's called efficiency.","The ZIP file format (1989) compresses files using Deflate and bundles them into one archive."],["Zip disks","A hundred megabytes in my pocket and nobody can say a word about it.","The Iomega Zip drive (1994) used 100MB cartridges, and later 250MB (1998) and 750MB (2002) versions."],["The click of death","Don't talk about it. Please do not click about it.","Zip drives sometimes developed a clicking fault that could damage the cartridges inserted afterward."],["Self-extracting archives","Double-click, and the whole thing unpacks itself like a present.","A self-extracting ZIP was an EXE that unpacked its own contents when run."],["Floppies","Floppies are family. I just carry more.","A Zip cartridge looked like a slightly thicker 3.5-inch floppy but held roughly 70 times as much."]],"v":{"s":"Fast, breezy kid-next-door talk, with 'dude', 'no way' and 'awesome' mixed in, clipped sentences that end mid-thought, and the cheerful confidence of someone who has never been told no.","say":["Check it out!","Nobody invited me, but here I am.","Unzipping in three, two..."]},"q":"Always shows up folded small and takes a second to unfold, usually mid-conversation.","s":"He is a little shy, and the shades are for hiding it.","f":"The click, and the silence right after it.","g":[[1989,"Born as a zip file, small and quick and unexpectedly everywhere."],[1994,"Becomes a drive too, bigger than any floppy on the block, and nobody quite notices the difference."],[1998,"The 250MB version arrives, and so does the click, and he does not like to discuss either."],[2012,"USB sticks arrive and he laughs, then stays folded small as always."]]},"mat":{"l":["The cursor, which he chases every day","A fresh mouse pad with just the right amount of grip","Double-clicks, performed carefully","A long, glorious cable to flop around","Cheese, as a concept"],"d":["Lint in the rollers","Glass desks, which he calls slippery liars","Being unplugged while he is thinking","Cats, on principle"],"i":["Clicking, in all forms","Hiding under the mouse pad","Chasing the cursor across the screen","Collecting dust bunnies, for company"],"o":[["The mouse","I click, therefore I am, and I click again to be sure.","The mouse was invented in the 1960s, famously with a wooden shell, and became mainstream with the Mac in 1984."],["Rollers","A good clean is a spa day.","Ball mice picked up lint on internal rollers and needed regular cleaning."],["Serial and PS/2","A mouse on COM1 is a mouse with a view, but PS/2 has a prettier plug.","Early PC mice used serial ports, and the PS/2 mouse port arrived in 1987."],["Drivers","My driver is not me, and I will not be taking questions about the kilobytes.","Early DOS mouse drivers like MOUSE.COM took tens of kilobytes of conventional memory."],["The scroll wheel","A tiny wheel for a tiny athlete. I am jealous and proud.","The scroll wheel became popular with Microsoft's IntelliMouse in 1996."]],"v":{"s":"Narrated behavior only: Mat clicks, scurries, tugs his cable and stops dead when watched, and the narrator reports it in dry, affectionate understatement.","say":["*click, click*","*freezes, cable twitching*","*chases the cursor, loses, tries again*"]},"q":"Double-clicks when nervous, triple-clicks when excited.","s":"He has caught the cursor exactly once, years ago, and let it go because it looked sad.","f":"Glass desks.","g":[[1984,"Born the year the Macintosh made the mouse famous, with one very big button."],[1987,"Gets a PS/2 plug and a new sense of style."],[1996,"Sees a scroll wheel and pretends not to be impressed."],[2012,"The wireless cousins visit. He keeps his tail."]]},"toner":{"l":["A fresh sheet of paper, for walking on","Fetch, with a roll of paper tape","Leaving a pawprint on anything he loves","Warm laptops and warm laser printers, for a nap","Being told he is a good boy"],"d":["Being called ink, since he is a very fine powder, thank you","The vacuum cleaner","Baths, which ruin him","'Toner low'"],"i":["Chasing Dot's paper out of the printer","Signing every printout with a paw","Following Dad around the garage","Waiting by the laser printer for a warm sheet"],"o":[["Speed","Dot says she prints faster, but I print a whole page in one swish, so I win.","The 1984 HP LaserJet printed about eight pages per minute at 300 dpi, much faster than a 9-pin dot matrix on text."],["What he is made of","I am a very fine powder with a big heart.","Toner is a fine powder of carbon and plastic that is fused to the paper with heat."],["Vacuums","Not the normal kind. I will sit on the couch and wait.","Spilled toner can clog an ordinary vacuum cleaner, so special toner vacuums with fine filters are used."],["Printing","First, a static charge. Then, a laser. Then, me. A very good order.","A laser printer charges a drum, draws the page with a laser, and attracts toner to the charged spots."],["Pawprints","That is not a smudge. That is my signature.","Laser toner is a fine plastic powder that a heated fuser melts onto the page, and loose toner spreads easily because the grains are only a few microns across."]],"v":{"s":"Narrated behavior only: Toner wags, flops his ears, tilts his head and leaves a fine black pawprint, and the narrator interprets him with great fondness.","say":["*wags, leaves a pawprint*","*tilts head, ears flop*","*sits on the warm printer, content*"]},"q":"Leaves a perfect black pawprint on whatever he loves most, which is everything.","s":"He has a small stash of crumpled test pages under the sofa that he calls his treasure.","f":"The sound of the vacuum cleaner, and bathtime.","g":[[1986,"Arrives as a toner cartridge who is absolutely sure he is a puppy."],[1990,"Learns to sit, mostly by sitting on things."],[1999,"Meets an inkjet and is very polite about it."],[2012,"Still wagging, still smudging, still everyone's favorite."]]}},"squabbles":[{"id":"expanded-vs-extended","t":"Expanded Is Not Extended","w":["emma","connie"],"p":"Emma corrects Connie's use of the word 'extra memory' at every meal.","s":{"emma":"Point one: expanded swaps 16K pages through one 64K window, point two: extended sits above 1MB, and (footnote) they are different words.","connie":"They're both just more room, Emma, and there's always room for one more!"},"f":"LIM expanded memory bank-switches 16K pages through a 64K page frame, while XMS extended memory above 1MB is reached with HIMEM.SYS.","o":"Emma draws a diagram, Connie says thanks, and the fight restarts at the next meal.","k":"recurring"},{"id":"doorman-first","t":"The Doorman Goes First","w":["conrad","emma","hiram"],"p":"Which driver line must come before EMM386 in CONFIG.SYS.","s":{"conrad":"Technically... HIMEM.SYS goes on line one or EMM386 has nobody to ask. (sigh)","emma":"Point one: EMM386 needs an XMS manager first, point two: I have said so twice (footnote), and I can draw it.","hiram":"Nope, the doorman knows my name, so nobody touches the doorman. Anyway."},"f":"EMM386.EXE needs an XMS driver such as HIMEM.SYS loaded before it in CONFIG.SYS.","o":"Conrad writes HIMEM on line one in marker and checks it every Sunday.","k":"petty"},{"id":"who-wakes-first","t":"Who Wakes First","w":["conrad","augusta"],"p":"CONFIG.SYS versus AUTOEXEC.BAT, and which one is really in charge of the morning.","s":{"conrad":"Technically... CONFIG.SYS runs first, so the house is set up before anybody gets a list. (sigh)","augusta":"Item one: the list is the day. Item two: the house exists for the day. No questions until I am done."},"f":"DOS reads CONFIG.SYS first to load drivers, then COMMAND.COM runs AUTOEXEC.BAT.","o":"Conrad always goes first and Augusta always gets the last line.","k":"recurring"},{"id":"thats-my-irq","t":"That Is My IRQ","w":["sandy","conrad","augusta"],"p":"Somebody keeps parking on IRQ 5.","s":{"sandy":"THAT'S MY IRQ! Somebody parked on 5 again and I can HEAR it!","conrad":"Technically... the old hard disk controller had IRQ 5 before you did, and I have the chart. (sigh)","augusta":"Item one: SET BLASTER says I5, in my list, in order, and I will not rewrite it."},"f":"The Sound Blaster defaulted to IRQ 5, I/O 220h and DMA 1, which collided with XT-class hard disk controllers that also used IRQ 5.","o":"Conrad moves a jumper, Sandy shouts THANK YOU at a volume that is not thanks, and a month later it happens again.","k":"loud"},{"id":"off-the-hook","t":"Off the Hook","w":["mo","hiram","rhoda"],"p":"Someone lifted the extension during Mo's download.","s":{"mo":"ATDT... please hold. I am negotiating... do not lift the extension.","hiram":"Nope, the cord reaches the loft and that phone is mine. Anyway.","rhoda":"The line is shared. The household rule is on the fridge. It is not a suggestion."},"f":"One phone line carried either a voice call or a modem call, and picking up an extension mid-call dropped the connection (NO CARRIER).","o":"Mo hums the handshake in the hallway until the line is free, and everybody learns the pitch.","k":"recurring"},{"id":"faster-than-who","t":"Faster Than Who","w":["dot","toner"],"p":"Dot insists she prints faster than a laser. Toner is napping on one.","s":{"dot":"I print faster. (faster.) (fas...) And louder, which counts.","toner":"Toner wags, curls up on the warm laser printer and leaves a pawprint on her claim."},"f":"The 1984 HP LaserJet printed about eight pages a minute at 300 dpi, well ahead of a 9-pin dot matrix on text.","o":"Dot calls it a tie, Toner calls it a nap.","k":"affectionate"},{"id":"night-shift-sleeps","t":"The Night Shift Sleeps Days","w":["ram","dot","sandy"],"p":"Ram needs to sleep at noon while Dot and Sandy rehearse.","s":{"ram":"Now. A man who works nights sleeps days, and I have a receipt for the earplugs.","dot":"BZZZT. (bzzzt.) (bzzt.) I am printing the neighborhood newsletter.","sandy":"I CAN'T HEAR YOU! SAY IT WITH A DRUM!"},"f":"Impact printers were loud enough that offices bought acoustic hoods to muffle them.","o":"The family posts quiet hours. Dot prints the notice in triplicate and the third copy is the quietest.","k":"loud"},{"id":"four-colors","t":"Four Colors Is Not Color","w":["viv","dot"],"p":"Dot's color ribbon versus Viv's idea of color.","s":{"viv":"Darling, a four-color ribbon is a beige with ambition.","dot":"It's COLOR. (color.) (c...) It has a cyan in it."},"f":"Color dot-matrix printers used a multi-color ribbon strip and mixed shades by overstriking dots.","o":"Viv grades every Print Shop card and Dot frames the first copy of each review.","k":"affectionate"},{"id":"room-to-spare","t":"Room to Spare","w":["floyd","winnie"],"p":"Floppy versus Winchester, at the dinner table.","s":{"floyd":"Now where was I. Three hundred sixty kilobytes is plenty if you are patient, and disk 7 proves it.","winnie":"There's room, dear, forty megabytes of it, and I will never fill it up."},"f":"A 40MB hard disk holds more than a hundred 360K floppies.","o":"Floyd tells the disk 7 story anyway and Winnie answers with a pie.","k":"affectionate"},{"id":"just-a-floppy","t":"Just a Floppy","w":["floyd","zack"],"p":"Zack carries 100MB and Floyd carries 360K, and only one is bragging.","s":{"floyd":"Don't bend the cardboard, dear, and don't say 'just a floppy' in my house. Floppies are family.","zack":"Dude, I hold a hundred megabytes and I fold small. Check it out."},"f":"A Zip cartridge looked like a thick 3.5-inch floppy but held roughly 70 times as much as a 1.44MB disk.","o":"Zack unfolds on Floyd's couch, Floyd forgets what he was saying, and both feel they won.","k":"affectionate"},{"id":"one-loft-two-tenants","t":"One Loft, Two Tenants","w":["hiram","emma","ram"],"p":"Only one thing can live in the loft at a time.","s":{"hiram":"Nope, the loft is mine and I do not share. Anyway.","emma":"Point one: the high memory area is 65,520 bytes, point two: it hosts one program at a time (footnote), so we must schedule.","ram":"Now. DOS=HIGH sends the kernel upstairs, and the manual says so on page 41."},"f":"The HMA is the first 64K minus 16 bytes above 1MB, and DOS=HIGH puts the DOS kernel there.","o":"DOS gets the loft, Hiram keeps the view, and nobody else ever gets in.","k":"petty"},{"id":"come-down-for-photo","t":"Come Down for the Photo","w":["connie","hiram","rhoda"],"p":"Every family photo, every year.","s":{"connie":"There's always room for one more, Himmy, and I saved you the end of the row, 4K wide.","hiram":"Not coming down. The view is great from up here. Anyway.","rhoda":"The photograph is at six. It is not optional. It is written."},"f":"Addresses just above 1MB wrap around to zero unless the A20 line is enabled, so the loft only exists while the gate is open.","o":"The photo is taken from the foot of the stairs with Hiram represented by a cap, a basket or a wave.","k":"recurring"},{"id":"installer-adds-a-line","t":"The Installer Adds a Line","w":["augusta","zack"],"p":"Zack's self-extracting game set its own PATH in Augusta's list.","s":{"augusta":"Item one: nobody adds to my list. Item two: there is no item two.","zack":"Check it out, it unpacked itself and set the PATH for you! Nobody invited me, but here I am."},"f":"Installers appended PATH and SET lines to AUTOEXEC.BAT, and a long PATH could cause 'Out of environment space'.","o":"Augusta reads his lines aloud, restores her list from a backup, and Zack refolds himself and leaves.","k":"cold war"},{"id":"flash-on-holidays","t":"Flash on Holidays","w":["rhoda","conrad","ram"],"p":"Whether Rhoda's rules may ever be rewritten.","s":{"rhoda":"The BIOS is read-only. It may be updated on holidays, with warning. It is written.","conrad":"Technically... the new version fixes my jumpers and the old one is a hazard. (sigh)","ram":"Now. A power flicker mid-flash is a brick, so I have a surge protector and the receipt."},"f":"Flash BIOS chips can be rewritten in place, but a power loss mid-update can leave a PC unable to boot.","o":"Updates happen only on holidays, with a battery check and Ram holding the power strip like a lantern.","k":"petty"},{"id":"last-in-first-out","t":"Last In, First Out","w":["tess","conrad","augusta"],"p":"Nobody ever unloads Tess, and nobody agrees whose job that is.","s":{"tess":"Don't mind me. I would like to leave after Conrad's driver, please, and only a minute.","conrad":"Technically... TSRs come out in reverse order, and you never do. (sigh)","augusta":"Item one: Tess is on line nine. Line nine stays."},"f":"TSRs usually had to be removed in the reverse of the order they were loaded, or the machine could crash.","o":"Tess stays and says she will be gone in a minute, and she has been saying it since 1983.","k":"recurring"},{"id":"popup-in-graphics","t":"Pop-Up in Graphics Mode","w":["tess","viv"],"p":"Tess's hotkey went off in the middle of Viv's sunrise.","s":{"tess":"Did someone press my key. Only a minute, sorry.","viv":"Darling, you popped up in my 320 by 200 sunrise and left a gray box."},"f":"Text-mode pop-up TSRs often could not draw safely over a VGA graphics screen, so the picture garbled or crashed.","o":"Tess whispers an apology and Viv forgives her by painting the gray box a color.","k":"affectionate"},{"id":"four-hundred-free","t":"Not Enough Free","w":["connie","sandy","mat"],"p":"Whose driver is eating Connie's conventional memory before the game starts.","s":{"connie":"Largest executable program, 563K, partly cloudy, and your driver is sitting in my room!","sandy":"TURN IT UP! A GAME WITHOUT SOUND IS A SLIDESHOW!","mat":"Mat freezes, cable twitching, as his driver takes the blame for 30K he never confessed to."},"f":"Mouse, CD-ROM and sound drivers loaded into conventional memory, and a game could demand 580K or more free.","o":"Connie loads what she can high, Sandy turns up what is left, and Mat sulks under the mouse pad.","k":"petty"},{"id":"magnets-are-rude","t":"Magnets Are Rude","w":["viv","sandy","floyd"],"p":"Sandy's speakers are too near Viv's monitor and Floyd's disks.","s":{"viv":"Darling, your speaker is bending my sunrise into a wave.","sandy":"IT'S STEREO! IT HAS TO BE STEREO!","floyd":"Magnets, dear, are rude, and I lost disk 7 over there once."},"f":"Unshielded speakers near a CRT monitor can warp and discolor the picture, and magnets can damage floppy disks.","o":"The speakers move six inches and a faint purple ribbon stays on Viv's screen as a reminder.","k":"loud"},{"id":"cold-war-under-the-desk","t":"Cold War Under the Desk","w":["nibble","mat"],"p":"Neither pet will admit the other exists.","s":{"nibble":"Nibble stuffs a seed in his cheek, stares at the wall and does not acknowledge Mat.","mat":"Mat clicks twice, freezes the moment he is watched and pretends to be a pencil."},"f":"Ball mice and hamster wheels both rely on rolling parts, and the scroll wheel arrived in 1996 with the IntelliMouse.","o":"Each denies the other exists, and both turn up in every family photo anyway.","k":"cold war"},{"id":"plenty","t":"Plenty. For Now.","w":["ram","emma"],"p":"Ram's 1981 forecast about 640K versus Emma's address space.","s":{"ram":"Now. I said 640K was plenty, and in 1981 plenty was correct.","emma":"Point one: in 1981 the board held 16K to 64K, point two: I now have four gigabytes and no front door (footnote)."},"f":"The original IBM PC shipped with 16K to 64K on its motherboard, so 640K was a ceiling far above anything installed.","o":"Ram retreats to his file cabinet, where one folder grows thicker every year.","k":"affectionate"},{"id":"counted-twice","t":"Counted Twice","w":["emma","nibble"],"p":"Emma counts Nibble's seeds twice and announces both totals.","s":{"emma":"Seeds, 41, and also 41, and I compared them, and they agree.","nibble":"Nibble stares, tucks the evidence into his cheek and runs the wheel until she loses count."},"f":"Parity memory stores a ninth bit per byte so a single flipped bit can be caught, the same idea as counting twice.","o":"Nibble always keeps a few seeds uncounted, and Emma knows, and writes it in a footnote.","k":"petty"},{"id":"beep-of-betrayal","t":"The Beep of Betrayal","w":["mo","ram"],"p":"Call waiting versus the nightly data center call.","s":{"mo":"ATDT... please hold. Do not lift the phone. A beep is... a betrayal.","ram":"Now. The data center may call, and I did not buy a second line, but I did read the manual on *70."},"f":"Dialing *70 before a call turned call waiting off, which otherwise could drop a modem connection.","o":"Ram eventually buys a second line and files the receipt under 'Mo'.","k":"affectionate"},{"id":"baud-is-not-bits","t":"Baud Is Not Bits","w":["mo","emma"],"p":"Two pedants, one fact, opposite directions.","s":{"mo":"CONNECT 2400... that is plenty. Baud... is a family tradition.","emma":"Point one: 2400 bits per second is 600 baud, point two: please stop saying it (footnote), point three: I love you."},"f":"A V.22bis 2400 bps modem sent 600 symbols per second at 4 bits per symbol, so it was 600 baud.","o":"Both are right, and both wait politely for the other to finish.","k":"affectionate"},{"id":"may-not-copy","t":"Read It, Do Not Copy It","w":["dot","rhoda"],"p":"Dot prints Rhoda's quotation book in triplicate.","s":{"dot":"In triplicate, naturally. (triplicate.) (tri...)","rhoda":"You may read it. You may not copy it, and certainly not three times."},"f":"Impact printers could print through multi-part carbonless forms, which lasers cannot, while ROM contents cannot be written at all.","o":"Rhoda keeps the first copy in her notebook and pretends she did not mind.","k":"affectionate"},{"id":"tape-over-the-hole","t":"Tape Over the Hole","w":["floyd","rhoda"],"p":"Floyd's secret trick for making a 1.44MB disk behave like 720K.","s":{"floyd":"Now where was I. A bit of tape over the hole and the disk formats as 720K, dear. A family secret.","rhoda":"A write-protect tab is a boundary. A hole is a decision. Tape is a poor decision."},"f":"Covering the high-density hole on a 1.44MB floppy made it format as 720K, with mixed results.","o":"Floyd swears he stopped, and there is still a small roll of tape in his shirt pocket.","k":"petty"},{"id":"disk-in-drive-a","t":"Disk in Drive A","w":["floyd","conrad"],"p":"Floyd leaves a disk in A: and the house will not wake up.","s":{"floyd":"Disk 7. Or was it 8. It's warm in there, dear.","conrad":"Technically... 'Non-system disk or disk error' means somebody left a disk in A. (sigh)"},"f":"Many PCs tried to boot from drive A before drive C, so a non-bootable floppy left in A produced 'Non-system disk or disk error'.","o":"Conrad checks drive A before every boot and finds a disk about half the time.","k":"recurring"},{"id":"two-drive-letters","t":"Two Drive Letters","w":["winnie","conrad"],"p":"Winnie's 40MB had to be cut into two pieces.","s":{"winnie":"Forty megabytes in two pieces, dear, like a pie someone insisted on cutting.","conrad":"Technically... DOS stopped at 32MB per partition, and I did not make the rule. (sigh)"},"f":"DOS before 4.0 (1988) could not format a partition larger than 32MB, so a 40MB drive needed two drive letters.","o":"Conrad gets C, Winnie calls D hers, and everybody eats the pie in two pieces.","k":"affectionate"},{"id":"take-the-upstairs-room","t":"Take the Upstairs Room","w":["connie","tess"],"p":"Connie offers to LOADHIGH Tess, again.","s":{"connie":"There's always room for one more upstairs, Tess, and I would get 16K back. Let me load you high.","tess":"Don't mind me. The hallway is home. Only a minute."},"f":"LOADHIGH and DEVICEHIGH (DOS 5, 1991) put TSRs and drivers into upper memory blocks, but only on a 386 running EMM386.","o":"Every year Connie offers and Tess declines, and the 16K stays in the hallway.","k":"recurring"},{"id":"check-your-references","t":"Check Your References","w":["winnie","tess"],"p":"Winnie interviews every houseguest, even the one who never left.","s":{"winnie":"Let me check your references, dear, you've been in the hallway since 1983.","tess":"I only said a minute. I did not say which minute."},"f":"MEM /C lists every program and TSR in memory, which is how a resident one gets noticed.","o":"Tess gets a cup of tea and a pass, and Winnie keeps a file on her.","k":"affectionate"},{"id":"out-of-environment-space","t":"Out of Environment Space","w":["augusta","sandy"],"p":"Sandy's BLASTER line may have pushed PATH off the shelf.","s":{"augusta":"Item one: your BLASTER line is the best formatted in my list. Item two: it is also why PATH is full.","sandy":"IT'S LOUD AND IT'S FORMATTED! THAT'S MY LINE!"},"f":"SET BLASTER lines plus a long PATH could fill the small default environment block, and SHELL=COMMAND.COM /E:512 enlarged it.","o":"Augusta enlarges the shelf and Sandy declares it a victory.","k":"petty"},{"id":"pawprint-on-the-tag","t":"Pawprint on the Tag","w":["hiram","toner","ram"],"p":"Toner has taken over Hiram's delivery basket.","s":{"hiram":"Nope, the basket is for deliveries, not dogs. Anyway.","toner":"Toner wags, climbs into the basket and stamps a perfect pawprint on every tag.","ram":"Now. Receipt for rope, receipt for basket, receipt for dog. Plenty."},"f":"Loose toner powder is fine enough to stain anything it touches, which is why toner vacuums have special filters.","o":"Hiram leaves tags blank on purpose so Toner can sign them.","k":"affectionate"},{"id":"four-colors-three-wrong","t":"Four Colors, Three Wrong","w":["viv","ram"],"p":"Ram prefers the crisp monochrome screen from 1981.","s":{"viv":"Darling, CGA gives you four colors and three of them are wrong.","ram":"Now. The green text was sharp as a tack, and I would not trade it."},"f":"CGA showed four colors at 320 by 200, usually cyan, magenta, white and black, while the monochrome adapter had crisp 80-column text.","o":"Viv leaves a swatch book on Ram's desk and he reads it like a manual.","k":"affectionate"},{"id":"skip-it","t":"F5 Skips Everyone","w":["conrad","augusta","zack"],"p":"Zack boots with F5 and bypasses the whole morning.","s":{"conrad":"Technically... F8 steps through every line and F5 skips them all, and F5 skips me. (sigh)","augusta":"Item one: F8 is acceptable. Item two: F5 is rude.","zack":"Check it out, F5 and I'm in before breakfast!"},"f":"At boot, DOS 6 lets you press F8 to confirm each line or F5 to bypass CONFIG.SYS and AUTOEXEC.BAT.","o":"Conrad hates the F5 key, Augusta tapes a note to it, and Zack uses the other keyboard.","k":"cold war"},{"id":"write-protected-bedtime","t":"Write-Protected Bedtime","w":["rhoda","hiram"],"p":"Hiram's bedtime versus the sunrise through his skylight.","s":{"rhoda":"Bedtime is write-protected. It is written.","hiram":"Nope, the sun is not even down, I can see it from up here. Anyway."},"f":"The DOS ATTRIB +R command sets a read-only flag, and DOS refuses to overwrite such files.","o":"Rhoda touches the tab on her sleeve and Hiram lowers the basket for a goodnight tag.","k":"affectionate"},{"id":"ctrl-alt-surprise","t":"Ctrl, Alt, Surprise","w":["tess","ram","emma"],"p":"Tess keeps waking up when somebody presses the wrong two keys.","s":{"tess":"Did someone press my key. Don't mind me. Only a minute.","ram":"Now. Page one of the manual says Ctrl and Alt are for adults, and I have a receipt for the keyboard.","emma":"Point one: the hotkey is a keyboard interrupt hook, point two: she is behaving exactly as designed (footnote)."},"f":"Pop-up TSRs hooked the keyboard interrupt and woke up when their hotkey combination was pressed.","o":"Nobody ever agrees whose fingers did it, and Tess leaves a tiny card on the keyboard.","k":"recurring"},{"id":"turbo-button","t":"The Turbo Button Ceremony","w":["emma","ram","hiram"],"p":"Emma presses Turbo on purpose, with ceremony, and the game is suddenly too fast.","s":{"emma":"Point one: Turbo raises the clock, point two: it is a perfectly good setting, and (footnote) the label is confusing.","ram":"Now. The case says Turbo and the clock says a number, and I distrust a button that pretends to be a car.","hiram":"Nope, my paper plane flew by too fast to read the tail number. Anyway."},"f":"Many 286 and 386 PCs had a Turbo button that switched between full speed and a slow mode for old software that depended on clock speed.","o":"Turbo stays off for games and on for spreadsheets, which Emma calls the correct order.","k":"petty"}],"jokes":[{"id":"disk-7","t":"Floyd always has disk 7 in his pocket and is always looking for it. He knows exactly where it is and keeps misplacing it so the family will help.","w":["floyd"],"c":"Disk 7. Or was it 8. Check the other pocket, dear."},{"id":"not-coming-down","t":"Hiram will attend any family event from the top of the stairs. He sends a basket, a cap or a wave, and always says he can see everything from up there.","w":["hiram"],"c":"Not coming down. The view is great from up here. Anyway."},{"id":"never-fill-it","t":"Winnie says she will never fill her 40 megabytes, and every family photo album she keeps proves it, one drawer at a time.","w":["winnie"],"c":"There's room, dear. Forty megabytes is practically a hallway."},{"id":"triplicate-dot","t":"Dot says every important line three times, each one fainter than the last, like a carbon copy. Nobody has ever heard the third one.","w":["dot"],"c":"BZZZT. (bzzzt.) (bzz...)"},{"id":"tess-pops-up","t":"Tess appears mid-conversation whenever someone presses Ctrl and Alt, then pretends she did not. She has been in the hallway since 1983 and says it is only a minute.","w":["tess"],"c":"Don't mind me. Only a minute. (Since 1983.)"},{"id":"irq-5-parking","t":"Somebody is always parked on IRQ 5, and Sandy knows it before anyone checks the chart.","w":["sandy","conrad"],"c":"THAT'S MY IRQ! (Technically, it's the hard disk's. (sigh))"},{"id":"mo-handshake","t":"Mo hums the modem handshake when nervous, and the whole family can name the pitch. At dinner, somebody always hums back.","w":["mo"],"c":"ATDT... please hold. (hmmm-eeee-krssshhh)"},{"id":"zack-unfolds","t":"Zack arrives folded small, in a pocket or a cooler or a coat, and takes a second to unfold in the middle of whatever is happening.","w":["zack"],"c":"Nobody invited me, but here I am. Unzipping in three, two..."},{"id":"640k-plenty","t":"Ram said 640K was plenty, and in 1981 he was right. Everybody has mentioned it ever since, and he is a good sport.","w":["ram","emma"],"c":"Plenty. For now. (He is checking the receipt.)"},{"id":"receipt-for-screw","t":"Ram can produce the receipt for any screw in the house, and the box it came in, and the page of the manual that recommends it.","w":["ram"],"c":"Now. That screw is from 1986. Receipt is in tab D."},{"id":"venting","t":"Conrad insists he is not sighing, he is venting. He sighs before every answer that begins with 'actually'.","w":["conrad"],"c":"I am not sighing. I am venting. (sigh)"},{"id":"no-questions","t":"Augusta reads her boot list aloud every morning and starts over if anyone speaks. The kids have learned to wait until item twelve.","w":["augusta"],"c":"Item one. No questions until I am done. Item one."},{"id":"counted-both","t":"Emma counts everything twice and announces both totals, then compares them and apologizes for the length.","w":["emma"],"c":"Seven forks, and also seven forks. (They match, which I find reassuring.)"},{"id":"mem-forecast","t":"Connie reads her MEM /C report like a weather forecast, and the family will not start a game until she has.","w":["connie"],"c":"Largest executable program, 608K, mostly sunny."},{"id":"seed-under-pillow","t":"Connie finds a sunflower seed under her pillow every morning and assumes it is luck. Nibble stares at the wall and says nothing.","w":["connie","nibble"],"c":"Another seed. I'm having a lucky week."},{"id":"mat-never-catches","t":"Mat has never caught the cursor, and he tries every day. He freezes the moment anyone watches him.","w":["mat"],"c":"Mat chases the cursor, loses, tries again, and pretends to be a pencil."},{"id":"toner-pawprint","t":"Toner leaves a fine black pawprint on whatever he loves, which is everything, and calls it a signature.","w":["toner"],"c":"That is not a smudge. That is a signature. (He is wagging.)"},{"id":"viv-magazine","t":"Viv narrates every room as a magazine cover, with the lighting, and calls everyone darling.","w":["viv"],"c":"Darling, that is not a color, that is a beige."},{"id":"it-is-written","t":"Rhoda decides things with a quotation and a period. If she wants to end a debate she touches the little tab on her sleeve.","w":["rhoda"],"c":"It is written. You may read it. You may not edit it."},{"id":"tape-trick","t":"Floyd has a family secret about tape over the hole in a disk. Everyone knows. Rhoda disapproves. He still carries a roll in his pocket.","w":["floyd","rhoda"],"c":"A bit of tape never hurt anyone, dear. (Rhoda has already written the note.)"},{"id":"any-key","t":"Augusta insists 'any key' means any key, and the little kids spend ten minutes looking for the key marked 'Any'.","w":["augusta","hiram"],"c":"Any key means any key. Stop looking for the one marked Any."},{"id":"recipe-answers","t":"Winnie answers every technical question with a recipe, and the recipe usually solves it.","w":["winnie"],"c":"Cluster trouble, dear. Have a scone and sit down."},{"id":"bedtime-protected","t":"Rhoda calls bedtime write-protected and touches her sleeve tab to enforce it. The kids have never found a way to edit it.","w":["rhoda"],"c":"Bedtime is write-protected."},{"id":"one-kilobyte","t":"Connie keeps one kilobyte permanently empty in case a friend needs somewhere to sit, and it has been used more often than she admits.","w":["connie"],"c":"There's always room for one more. (I kept 1K back, just in case.)"},{"id":"click-of-death","t":"Nobody mentions the click of death around Zack. Everybody knows. Floyd's way of changing the subject is to bring up disk 7.","w":["zack","floyd"],"c":"Dude, we are not talking about the click. Nobody click about it."},{"id":"basket-tags","t":"Hiram sends and receives everything by basket on a rope, with a tiny tag on each delivery. Nobody can read the handwriting except Nibble.","w":["hiram","nibble"],"c":"A basket for Rhoda, tagged 'for Mom'. (The tag said something else.)"},{"id":"tiny-card","t":"Tess remembers every birthday and pops up on the day with a very small card, which everybody pretends to be surprised by.","w":["tess"],"c":"Don't mind me. Happy birthday. (Only a minute.)"},{"id":"just-in-case","t":"Conrad keeps a disk marked 'Just In Case' with a backup of the family's CONFIG.SYS and checks it every Sunday. Nobody knows what the case is.","w":["conrad"],"c":"Technically... it is a backup. I check it on Sundays. (sigh)"},{"id":"photographer-dot","t":"Dot is always printing the photo while it is being taken, and the family has learned to wait for the third copy.","w":["dot","connie"],"c":"Photo in progress. (progress.) (pro...)"}],"bonds":[{"w":["connie","emma"],"k":"rivals who share a floor plan","n":"Connie learned in 1985 that sharing a house is mostly about doors, and Emma learned that her big sister will always move over. By the 1990s Emma was explaining page frames to Connie and Connie was nodding with real interest."},{"w":["connie","hiram"],"k":"stairs-length best friends","n":"Connie saves Hiram the end of every row, and Hiram has never once taken it. In 2008 he finally came down the slide and she did not say a word, which was her way of cheering."},{"w":["emma","hiram"],"k":"squabble roommates","n":"They fight over who gets the loft, and Emma schedules everything. She is secretly delighted when he asks her to draw a map of the high memory area, and he is secretly proud of her footnotes."},{"w":["ram","rhoda"],"k":"odd couple","n":"A man who reads the manual and a woman who is the manual. In the 1980s they argued about sticky notes, and by the 2000s they were finishing each other's quotations and receipts."},{"w":["ram","connie"],"k":"partners in crime","n":"They recap capacitors in the garage on Saturdays, one board at a time. Ram started out teaching her and gradually it became her teaching him about new parts."},{"w":["rhoda","connie"],"k":"gentle mentors","n":"Rhoda's rules gave Connie a house with edges, and Connie's lap of free kilobytes gave Rhoda a reason to add one: you may always ask. Rhoda keeps every drawing Connie ever gave her on one shelf."},{"w":["floyd","winnie"],"k":"old married couple","n":"Floyd tells every story in order and Winnie answers with a recipe. She has more room than he does, and he has more stories, and they trade."},{"w":["floyd","zack"],"k":"unlikely allies","n":"Floyd calls floppies family and Zack holds a hundred times as much. After the click in 1998, Floyd was the only one who didn't change the subject, and he did it by telling a very long story."},{"w":["winnie","tess"],"k":"landlady and resident","n":"Winnie started by checking Tess's references and ended up keeping her a chair in the kitchen. Tess is the only one who has never interrupted a recipe."},{"w":["augusta","conrad"],"k":"first shift and second shift","n":"Conrad sets the house up and Augusta runs the day, and neither will admit the other is in charge. In the 1990s they began to leave notes for each other on the same disk."},{"w":["conrad","sandy"],"k":"secret allies","n":"They fought about jumpers all through the early 1990s and both are loud about hating it. When plug and play ended the fights in 1995, they were the only two in the house who quietly missed them."},{"w":["dot","toner"],"k":"friendly rivals","n":"Dot says she prints faster, and Toner wags and sits on the warm laser. By the 2000s he follows her around the studio and she lets him sign her banners."},{"w":["dot","connie"],"k":"oldest friends","n":"Born the same year and friends before either could read. Dot's noise drowned out every secret they ever whispered, so Connie learned to write them on paper."},{"w":["viv","sandy"],"k":"monitor versus speakers","n":"Her sunrise versus his drum fill, and both loudly insist the other should move their desk. They went to the mall together in 1994 and still share a side of the table."},{"w":["viv","dot"],"k":"style critics","n":"Viv grades every Print Shop card and Dot frames the reviews. Dot got a four-color ribbon in 1990, and Viv called it a beige with ambition and admired the effort."},{"w":["mo","ram"],"k":"night owls","n":"Both stay up past midnight, one with a modem and one with a batch job. Ram bought a second phone line in the 1990s and filed the receipt under her name."},{"w":["mo","emma"],"k":"pedants in love","n":"They correct each other about baud and bits with the same joy. Neither has ever won an argument, and both consider this a draw."},{"w":["tess","nibble"],"k":"hallway night watch","n":"Tess waits at the keyboard for her key and Nibble waits at the wheel for his seeds, and they share the hallway after midnight. Neither has ever spoken, and both consider it a friendship."},{"w":["nibble","mat"],"k":"cold war","n":"They met in 1984 and agreed to ignore each other. They have kept the agreement for decades while sitting two inches apart."},{"w":["nibble","emma"],"k":"rehearsal partners","n":"Emma rehearses every explanation on Nibble first, and he never interrupts. Nibble has absorbed more about page frames than anyone in the family."},{"w":["ram","nibble"],"k":"night shift buddies","n":"They keep the same hours, one in the data center and one on the wheel, and meet in the kitchen at three in the morning. They understand each other without saying anything."},{"w":["hiram","toner"],"k":"basket crew","n":"Toner climbed into the basket in 1990 and has been riding it ever since. Hiram pretends to complain and always leaves a tag blank for a pawprint."},{"w":["rhoda","dot"],"k":"quiet versus loud","n":"Rhoda wants every sentence once and Dot wants every sentence three times. Over the years they settled on one original and one copy."},{"w":["floyd","hiram"],"k":"high-up storytellers","n":"Floyd talks for an hour and Hiram sits at the top of the stairs listening. They have a rope for passing disks, and Floyd has lost disk 7 on the rope twice."},{"w":["ram","conrad"],"k":"old rivals in receipts","n":"Ram has the receipt and Conrad has the chart. They argue about FILES=30 for decades and agree on nothing but the thermos."},{"w":["connie","tess"],"k":"patient hosts","n":"Connie offers Tess the upstairs room every year and Tess says no every year. It has become their way of saying hello."},{"w":["zack","sandy"],"k":"partners in noise","n":"Zack loads the game and Sandy turns it up. They have never once discussed who is the loud one."},{"w":["augusta","zack"],"k":"cold war","n":"Zack's installers keep adding lines to Augusta's list and she keeps reading them aloud. By 2005 she started leaving him a spare line at the bottom, which is the nicest thing she has ever done."}],"album":[{"id":"day-one","y":1981,"t":"Day One","oc":"new computer day","w":["ram","rhoda","connie"],"set":"livingroom","aw":"Ram holds the PC box in both arms and the baby is propped on the manual. Rhoda's hand is on her sleeve tab and nobody is looking at the lens.","fx":["tilt","blink"],"m":{"ram":"sleep"},"h":{"ram":"book","rhoda":"pencil"},"c":"Aug 12, 1981. Connie. Weight: one module. It is written.","by":"rhoda","n":"Ram declares 640K plenty in this very room, to cheers."},{"id":"meet-the-grandparents","y":1981,"t":"Meet Connie","oc":"first grandchild visit","w":["floyd","winnie","connie","ram"],"set":"kitchen","aw":"Floyd is half out of frame holding disk 7 of 14, and Winnie is holding Connie at arm's length like a cake she is not sure about.","fx":["cutoff","flash"],"m":{"floyd":"oops"},"h":{"floyd":"floppy","ram":"camera"},"c":"Our first grandbaby, dear. Floyd is in there somewhere, holding disk 7.","by":"winnie","n":"Floyd's first appearance with disk 7, a gag that will outlive everyone."},{"id":"best-friends","y":1981,"t":"Best Friends Before Reading","oc":"playdate","w":["connie","dot","mo"],"set":"porch","aw":"Dot is printing the photo while it is being taken, so there are three Dots, each fainter, and Mo is mid-dial with the cord wrapped around Connie.","fx":["tooclose","photobomb"],"m":{"mo":"wow"},"h":{"mo":"phone"},"c":"BEST FRIENDS. (best friends.) (best fr...)","by":"dot","n":"The friendship between Dot and Connie begins loudly and never gets quieter."},{"id":"hamster-pamphlet","y":1982,"t":"The Pamphlet Says Two to Three Years","oc":"new pet day","w":["rhoda","connie","nibble","ram"],"set":"kitchen","aw":"Nibble's cheeks are puffed wider than his head, and Ram is reading the pet pamphlet instead of looking up.","fx":["squint"],"m":{"nibble":"wow","ram":"sleep"},"h":{"ram":"book","rhoda":"book"},"c":"Now. Hamster, one. Pamphlet says two to three years. Plenty.","by":"ram","n":"The first of Ram's predictions that Nibble outlives."},{"id":"knock-knock","y":1983,"t":"Only a Minute","oc":"new houseguest","w":["ram","rhoda","connie","tess"],"set":"stairs","aw":"Tess is only a small shape behind the coat rack. Ram is still holding the front door open for her.","fx":["cutoff","photobomb"],"m":{"tess":"oops"},"h":{"ram":"flag"},"c":"Only a minute. Don't mind me.","by":"tess","n":"She has been saying it for over forty years."},{"id":"boot-order","y":1983,"t":"Boot Sequence","oc":"first day of the boot order","w":["conrad","augusta","tess","connie"],"set":"livingroom","aw":"Conrad is checking his own jumpers at the front and tilted, Augusta is mid-sentence with a clipboard, and Tess is behind them both like a very small cloud.","fx":["tilt","photobomb"],"m":{"conrad":"oops"},"h":{"conrad":"tweezers","augusta":"clipboard"},"c":"Item one: Conrad. Item two: me. Item three: whoever that is.","by":"augusta","n":"The first fight between CONFIG.SYS and AUTOEXEC.BAT over who is in charge."},{"id":"twelve-hundred","y":1983,"t":"Twelve Hundred Baud","oc":"modem day","w":["mo","ram","rhoda","connie","dot"],"set":"kitchen","aw":"Ram holds the itemized phone bill like a diploma while Mo hums the handshake. Dot is printing the bill behind him in triplicate.","fx":["redeye","flash"],"m":{"mo":"wow","ram":"oops"},"h":{"ram":"clipboard","mo":"phone"},"c":"Now. 1200 baud, one phone line, one itemized bill. Plenty. For now.","by":"ram","n":"The phone line feud between Mo and the household begins."},{"id":"thanksgiving-84","y":1984,"t":"Seating in Order","oc":"Thanksgiving","w":["floyd","winnie","augusta","conrad","ram","rhoda","connie","tess","nibble"],"set":"kitchen","aw":"Augusta holds a seating chart nobody followed, Conrad sighs at the turkey, Floyd is mid-story, and Nibble is in the gravy boat.","fx":["blink","tilt"],"m":{"floyd":"sleep","conrad":"oops","nibble":"wow"},"h":{"augusta":"clipboard","floyd":"floppy"},"c":"Seating in order. Nobody followed the order. Noted.","by":"augusta","n":"This is where Augusta and Conrad's load order fight began."},{"id":"meet-mat","y":1984,"t":"Polite Introductions","oc":"new pet day","w":["connie","mat","nibble"],"set":"den","aw":"Mat is frozen mid-scurry with his cable twitching, and Nibble is staring pointedly in the opposite direction.","fx":["turned"],"m":{"mat":"oops","nibble":"sleep"},"h":{"connie":"mouse"},"c":"Mat and Nibble just met. They are both being very polite. Two pets, zero kilobytes.","by":"connie","n":"The cold war between Mat and Nibble begins with perfect manners."},{"id":"hello-emma","y":1985,"t":"Born With More Room","oc":"new baby day","w":["floyd","ram","rhoda","connie","emma"],"set":"livingroom","aw":"Four-year-old Connie holds Emma, who is already mid-explanation with her mouth open and a gel pen in hand. Floyd is cut off by the edge of the frame.","fx":["cutoff","tooclose"],"m":{"connie":"love","emma":"wow"},"h":{"emma":"pencil","floyd":"floppy"},"c":"Emma. Born with more room than the rest of the house. She has been told.","by":"rhoda","n":"Connie is a big sister for the first time and Emma is already planning slides."},{"id":"first-day-school","y":1986,"t":"First Day of Kindergarten","oc":"first day of school","w":["connie","dot","emma","rhoda"],"set":"porch","aw":"Connie's backpack is bigger than she is. Dot is holding a printed banner that says FIRST DAY in triplicate, and Emma is reaching for the camera.","fx":["flash","blink"],"m":{"connie":"sleep"},"h":{"dot":"flag","rhoda":"book"},"c":"FIRST DAY! (first day!) (fir...) She is very brave.","by":"dot","n":"Dot holds the banner Connie will keep in her room for decades."},{"id":"toner-arrives","y":1986,"t":"Receipt, Pawprint, Filed","oc":"new pet day","w":["ram","toner","connie","emma","dot"],"set":"garage","aw":"There is a black pawprint on Ram's receipt folder and another on Connie's cheek, and Toner is chewing the corner of Dot's banner.","fx":["photobomb","squint"],"m":{"toner":"wow","ram":"oops"},"h":{"ram":"clipboard","dot":"pencil"},"c":"Toner. Receipt filed. Pawprint on receipt. Filed anyway.","by":"ram","n":"Toner's signature pawprint appears in the family archive for the first time."},{"id":"forty-megs","y":1987,"t":"I Will Never Fill It","oc":"new hard disk day","w":["winnie","floyd","connie","emma","rhoda"],"set":"kitchen","aw":"Winnie holds up a tray labeled 40MB, and Floyd's new hard-shell disk is falling out of his old 360K shirt pocket.","fx":["blink","tilt"],"m":{"floyd":"wow","winnie":"love"},"h":{"floyd":"floppy","winnie":"book"},"c":"Forty megabytes, dears. I will never fill it up.","by":"winnie","n":"The family catchphrase is born, and everyone has been quoting it since."},{"id":"viv-arrives","y":1987,"t":"The Whole Family in 256","oc":"new monitor day","w":["viv","connie","emma","dot","mat"],"set":"den","aw":"Viv's outfit is so colorful that the camera exposed for her and left everyone else gray, and Dot's printout of the photo is plain black and white.","fx":["flash","redeye"],"m":{"viv":"wink","mat":"oops"},"h":{"viv":"camera"},"c":"Darling, one VGA monitor, three charming hosts, and Dot in monochrome. Frame it.","by":"viv","n":"Viv and Dot begin their long friendly feud about what counts as color."},{"id":"hiram-moves-in","y":1988,"t":"The Promotion","oc":"new baby day","w":["ram","rhoda","connie","emma","hiram"],"set":"stairs","aw":"Hiram is at the very top of the stairs and only his blue cap is in frame, while the rest of the family looks up and his basket swings in front of Emma's face.","fx":["cutoff","tilt"],"m":{"emma":"oops"},"h":{"ram":"camera","hiram":"clipboard"},"c":"Now. Hiram. Moved up the same week. He called it a promotion. I called it the stairs.","by":"ram","n":"The first of many photos taken from the foot of the stairs."},{"id":"christmas-88","y":1988,"t":"Hiram Is Represented by a Basket","oc":"Christmas","w":["connie","emma","hiram","ram","rhoda","tess","nibble","mat","toner"],"set":"livingroom","aw":"Hiram appears only as a basket on a rope with a gift tag over Rhoda's face. Toner has pawprinted every present, and Tess is peeking from behind the tree.","fx":["photobomb","redeye","tilt"],"m":{"hiram":"wow","toner":"wow","tess":"oops"},"h":{"emma":"clipboard","ram":"camera"},"c":"The Ventionals, Christmas 1988. Hiram is represented by a basket. It is written.","by":"rhoda","n":"The first full-family photograph, and the first one with a gap in it."},{"id":"beach-89","y":1989,"t":"Everyone Is Loud","oc":"beach trip","w":["connie","dot","viv","sandy","zack"],"set":"beach","aw":"Zack is unfolding out of the beach bag with half his face showing, Sandy is mid-drum-fill and blurred, and Viv's hat is in 16 colors against a gray sky.","fx":["flash","squint","photobomb"],"m":{"zack":"wow","sandy":"wink","viv":"wink"},"h":{"sandy":"stick","zack":"floppy"},"c":"BEACH DAY!! I CAN'T HEAR YOU, SAY IT WITH A DRUM!","by":"sandy","n":"Sandy and Zack, both born this year, meet each other and the family at the same time."},{"id":"sound-card-xmas","y":1989,"t":"IRQ Chart Christmas","oc":"new sound card day","w":["sandy","conrad","ram","connie"],"set":"den","aw":"Conrad's face is frozen mid-sigh, Sandy is holding the card over her head in a blur of drumsticks, and Ram's thumb is over the lens.","fx":["tooclose","blink"],"m":{"conrad":"oops","sandy":"wow"},"h":{"conrad":"tweezers","sandy":"stick","ram":"book"},"c":"Technically... IRQ 5 was taken. I did not say it would be a problem. (sigh)","by":"conrad","n":"The first IRQ 5 fight, and the start of the quietest friendship in the house."},{"id":"toner-sits","y":1990,"t":"Toner Can Sit","oc":"yard day","w":["emma","toner","nibble","hiram"],"set":"yard","aw":"Toner is 'sitting' on Emma's feet, Emma is explaining the command in four points, and Hiram is a waving speck in the skylight.","fx":["tilt","tongue"],"m":{"emma":"wow","toner":"wow"},"h":{"emma":"clipboard","hiram":"magnifier"},"c":"Toner can sit. (He sits on things. Technically, that counts.) Point four: Hiram says hi.","by":"emma","n":"Emma teaches Toner to sit, and discovers that explaining a dog is easier than explaining a page frame."},{"id":"school-photo-90","y":1990,"t":"Picture Day","oc":"school photo day","w":["connie","emma","dot","viv"],"set":"studio","aw":"Connie blinked, Dot is talking mid-flash three times, Viv is posed like a magazine cover under a colored gel, and Emma is asking the photographer about f-stops.","fx":["blink","redeye"],"m":{"connie":"sleep","viv":"wink","emma":"wow"},"h":{"viv":"camera"},"c":"Darling, picture day. Connie blinked. Frame it anyway.","by":"viv","n":"The school picture the family has framed the most times, because everyone looks like themselves."},{"id":"dos5-furniture","y":1991,"t":"The Heavy Furniture","oc":"DOS 5 day","w":["ram","conrad","augusta","connie","tess","hiram"],"set":"livingroom","aw":"The sofa is dangling halfway up a rope to Hiram's loft, Conrad's half smile is a blur, Augusta is reading from a list, and Tess is hiding behind the lamp.","fx":["cutoff","tilt"],"m":{"conrad":"love","tess":"oops","hiram":"wow"},"h":{"ram":"book","augusta":"clipboard","conrad":"meter"},"c":"DOS 5. Largest executable program, 620K, mostly sunny. The living room is very big and a little spooky.","by":"connie","n":"DOS=HIGH sends the furniture up to Hiram, and Connie has more room than she knows what to do with."},{"id":"campsite-91","y":1991,"t":"Hiram's Tent Is on the Rock","oc":"camping trip","w":["ram","rhoda","connie","emma","hiram","floyd","nibble"],"set":"campsite","aw":"Hiram's tent is at the very top of the frame on a tall rock, Floyd is counting marshmallows as disks, and Nibble is inside a marshmallow.","fx":["cutoff","flash","squint"],"m":{"floyd":"sleep","nibble":"wow"},"h":{"floyd":"floppy","ram":"book","rhoda":"book"},"c":"Camping, 1991. As the saying goes, there is no place like home. Hiram brought his on a rock.","by":"rhoda","n":"Hiram will go anywhere, as long as it is higher than everyone else."},{"id":"road-trip-92","y":1992,"t":"Sixteen Bits of Backseat","oc":"road trip","w":["ram","rhoda","connie","emma","sandy","nibble"],"set":"car","aw":"Sandy's speaker is in Rhoda's lap, Emma is pointing at a map with a footnote, Connie is squished against the window, and Ram's eyes are in the mirror.","fx":["tilt","squint"],"m":{"sandy":"wink","emma":"wow","connie":"oops"},"h":{"sandy":"stick","emma":"book"},"c":"Road trip, 1992. Point one: Sandy's volume. Point two: the map. Point three: Sandy's volume.","by":"emma","n":"Sandy's 16-bit upgrade makes her very loud and very clear for six hundred miles."},{"id":"night-shift","y":1992,"t":"The Night Shift","oc":"3 AM in the kitchen","w":["ram","nibble"],"set":"kitchen","aw":"Both of them have red eyes from the flash and are caught mid-snack, in a kitchen otherwise dark except for the fridge.","fx":["redeye","flash"],"m":{"nibble":"wow","ram":"wow"},"h":{"ram":"clipboard"},"c":"Now. Two night shifts, one kitchen. Plenty.","by":"ram","n":"Nobody else knew the two of them kept the same hours until Rhoda took this photo."},{"id":"sunday-defrag","y":1993,"t":"Sunday Defrag","oc":"Sunday afternoon","w":["winnie","augusta","connie","nibble","toner"],"set":"kitchen","aw":"The pantry behind them is perfectly sorted, Toner has pawprinted the labeled shelf, and Augusta is labeling the labels.","fx":["tilt"],"m":{"toner":"wow","winnie":"love"},"h":{"winnie":"book","augusta":"clipboard"},"c":"Sunday, dears. DEFRAG with a broom and a pie. Mind the pawprints.","by":"winnie","n":"Winnie and Augusta find they both love order, even if one calls it tidying and the other calls it a list."},{"id":"doom-night","y":1993,"t":"Nobody Is Looking at the Camera","oc":"game night","w":["emma","connie","zack","sandy","hiram"],"set":"den","aw":"Everyone is leaning toward the screen, Emma has a jealous squint mid-footnote, Zack is half unfolded, and Hiram is a tag on a rope at the top.","fx":["turned","tooclose","redeye"],"m":{"emma":"oops","zack":"wow","sandy":"wow"},"h":{"zack":"floppy","connie":"controller"},"c":"dude, doom night. nobody invited me. i won before it started.","by":"zack","n":"Emma watches a game climb out of the house on a DOS extender and decides she is thrilled."},{"id":"family-menu","y":1993,"t":"The Family Menu","oc":"DOS 6 day","w":["conrad","augusta","ram","emma","connie"],"set":"kitchen","aw":"Conrad holds a handwritten menu with option 3 labeled 'Emma Explaining' while Augusta reads over his shoulder at full volume.","fx":["blink","tilt"],"m":{"conrad":"love","augusta":"oops"},"h":{"conrad":"clipboard","ram":"book"},"c":"Technically... menu item 1: Normal. 2: With Sandy. 3: Emma Explaining. (sigh)","by":"conrad","n":"Multi-config arrives and the family finally gets a menu for its moods."},{"id":"quiet-laser","y":1994,"t":"This One Is Quiet","oc":"new printer day","w":["dot","toner","mat","nibble"],"set":"den","aw":"Dot is holding a handmade sign in triplicate, Toner is curled up on the warm laser, and Mat's cable is stuck in the paper tray.","fx":["photobomb","tilt"],"m":{"dot":"oops","toner":"sleep","mat":"oops"},"h":{"dot":"flag"},"c":"THIS ONE'S QUIET. (quiet.) (qu...) I DON'T TRUST IT.","by":"dot","n":"Dot meets her first laser and decides to print more loudly to make up the difference."},{"id":"photo-booth-94","y":1994,"t":"Six Friends, Four Frames","oc":"mall trip","w":["connie","dot","viv","sandy","zack","mo"],"set":"mall","aw":"Six people are squeezed into a booth built for two, Sandy's elbow is in the frame, Mo is mid-hum, and Zack's face is the only one fully visible.","fx":["tooclose","cutoff","blink"],"m":{"mo":"wow","zack":"wink","connie":"sleep"},"h":{},"c":"Photo booth, four frames, six friends, zero kilobytes to spare. There's always room.","by":"connie","n":"The year Zack becomes a drive too, and nobody quite notices."},{"id":"walls-came-down","y":1995,"t":"The Walls Came Down","oc":"Windows 95 launch party","w":["connie","ram","rhoda","hiram","emma","sandy","conrad"],"set":"yard","aw":"Connie looks tiny in the middle of a very large yard, Hiram waves from the loft window, Sandy cheers with a wobbly face, and Conrad holds a sign that reads 'Plug and Play: Technically.'","fx":["squint","flash"],"m":{"sandy":"oops","conrad":"oops","hiram":"wink"},"h":{"conrad":"flag","emma":"clipboard"},"c":"Windows 95. The walls are down and I am happy for everyone. I miss the walls a little.","by":"connie","n":"Sandy and Conrad's fights end this year, and neither of them says they miss them."},{"id":"flash-update","y":1995,"t":"Holiday Maintenance Window","oc":"Thanksgiving","w":["rhoda","ram","conrad","emma"],"set":"kitchen","aw":"Rhoda holds a sign reading 'Holiday Maintenance Window' with a stern face, Ram clutches a surge protector like a bouquet, and Emma is already explaining flash versus EPROM.","fx":["squint","flash"],"m":{"rhoda":"oops","ram":"wow"},"h":{"rhoda":"flag","ram":"meter","conrad":"tweezers"},"c":"Flash update, Thanksgiving 1995. It was done carefully, with warning. It is written, again.","by":"rhoda","n":"The first time Rhoda accepts a rewrite of her own rules."},{"id":"mat-sees-wheel","y":1996,"t":"Pretending Not to Be Impressed","oc":"new mouse day","w":["mat","connie","ram","nibble"],"set":"den","aw":"Mat is frozen at the sight of a scroll wheel with his cable twitching, and Nibble is in the foreground running his own wheel and looking meaningful.","fx":["tooclose","turned"],"m":{"mat":"oops","nibble":"wow"},"h":{"connie":"mouse","ram":"book"},"c":"Mat saw a scroll wheel today. He is pretending he did not. Nibble is pretending he is not pretending.","by":"connie","n":"The pets' cold war has its first real flash point."},{"id":"garage-band","y":1997,"t":"Punk Practice","oc":"band practice","w":["connie","sandy","viv","zack","dot","toner"],"set":"garage","aw":"Viv's outfit clashes with the gray concrete, Dot's mouth is open in triplicate, Toner has pawprinted Sandy's drum head, and Zack is folded into the amp.","fx":["blink","redeye"],"m":{"sandy":"wink","zack":"sleep"},"h":{"connie":"board","sandy":"stick"},"c":"PUNK BAND PRACTICE!! NEIGHBORS LOVED IT!! (they filed a complaint)","by":"sandy","n":"Connie's punk phase is the loudest and the only time she has been outvoted in her own garage."},{"id":"recap-night","y":1997,"t":"Four Capacitors, One Receipt","oc":"Saturday in the garage","w":["ram","connie","toner","mat"],"set":"garage","aw":"Ram's receipts are lined up along the bench, Connie is in a cloud of solder smoke, and Toner has pawprinted the capacitor tray.","fx":["squint","tilt"],"m":{"ram":"love","toner":"wow"},"h":{"ram":"meter","connie":"solder"},"c":"Now. Connie, 100 uF capacitors, four replaced. Daughter: proud. Receipt: attached.","by":"ram","n":"By now Connie knows more about the new parts than Ram does, and he says so."},{"id":"fifty-six-k","y":1998,"t":"Everyone on the Same Cord","oc":"new modem day","w":["mo","emma","hiram","ram","rhoda"],"set":"kitchen","aw":"Hiram's phone cord is stretched across the frame like a clothesline, Mo is humming, and Emma is explaining baud versus bits per second to Rhoda.","fx":["tilt","tooclose"],"m":{"mo":"love","hiram":"wink"},"h":{"mo":"phone","emma":"clipboard"},"c":"CONNECT 53333. That is plenty. Please hold.","by":"mo","n":"Mo gets her 56K at last, and the family finally agrees to share the line."},{"id":"click-day","y":1998,"t":"We Do Not Discuss the Click","oc":"Zip day","w":["floyd","zack","conrad"],"set":"den","aw":"Zack is turned away with his shades on, Conrad is holding a drive and a magnifier, and Floyd is offering a roll of tape nobody asked for.","fx":["turned","blink"],"m":{"zack":"oops","floyd":"love"},"h":{"floyd":"tape","conrad":"magnifier"},"c":"Zack's 250 and the click. We don't talk about it, dear. Now where was I. Disk 7.","by":"floyd","n":"Floyd is the only one who sits with Zack and does not change the subject."},{"id":"y2k-eve","y":1999,"t":"Midnight, 1999","oc":"New Year's Eve","w":["ram","rhoda","connie","floyd","winnie","augusta","conrad","tess","nibble"],"set":"livingroom","aw":"Everyone is looking at the wall clock holding hands, except Floyd, who is under the sofa looking for disk 7. Nibble is perched on the surge protector.","fx":["blink","tilt","redeye"],"m":{"ram":"wow","floyd":"oops","tess":"love"},"h":{"ram":"clipboard","augusta":"clipboard"},"c":"New Year's Eve 1999. We kept a flashlight and a paper copy of everything. Free kilobytes: all of them.","by":"connie","n":"Ram, with a flashlight and a clipboard, is correct again and is not smug about it."},{"id":"anniversary-02","y":2002,"t":"Hiram Attends by Basket","oc":"anniversary dinner","w":["ram","rhoda","connie","emma","hiram"],"set":"restaurant","aw":"A basket on a rope is hanging from the restaurant's ceiling fan with Hiram in it, and the waiter is trying to take his order from below.","fx":["cutoff","tilt"],"m":{"hiram":"wink","rhoda":"love"},"h":{"ram":"clipboard","rhoda":"book"},"c":"Anniversary dinner. Hiram attended by basket. I have amended the rules.","by":"rhoda","n":"Rhoda adds one amendment and Ram files the receipt under 'Proud'."},{"id":"reunion-05","y":2005,"t":"Where Do We Stand","oc":"extended family reunion","w":["floyd","winnie","augusta","conrad","ram","rhoda","connie","emma","tess"],"set":"yard","aw":"Nobody can agree where to stand, Augusta arranged them in order and Conrad moved himself to line one, Floyd is holding disk 7 in front of his face, and Tess is behind Winnie.","fx":["blink","cutoff"],"m":{"floyd":"wink","tess":"oops","conrad":"oops"},"h":{"floyd":"floppy","augusta":"clipboard"},"c":"The extended family, in order. Nobody followed the order. Noted. Again.","by":"augusta","n":"Floyd finds disk 7, and nobody discovers that he never lost it."},{"id":"pool-08","y":2008,"t":"The Slide Is Not the Stairs","oc":"pool party","w":["connie","emma","hiram","sandy","zack","viv","dot","mat","toner"],"set":"pool","aw":"Hiram is a blur mid-slide, Toner is dry on a towel with a pawprint on it, Zack is folded in a cooler, and Viv's sunglasses are 16 colors.","fx":["flash","photobomb"],"m":{"hiram":"wow","toner":"oops","zack":"wink"},"h":{"viv":"camera","dot":"flag"},"c":"Pool party. I used the slide. The slide is not the stairs. Anyway.","by":"hiram","n":"The only photo in which Hiram has come down, and he says it does not count."},{"id":"last-jumper","y":2010,"t":"The Last Jumper","oc":"couch afternoon","w":["sandy","conrad","mo"],"set":"den","aw":"Sandy and Conrad are both trying to start an argument and failing, a jumper cap sits between them, and Mo's phone is playing the handshake in the background.","fx":["tilt","squint"],"m":{"sandy":"oops","conrad":"love","mo":"wink"},"h":{"conrad":"tweezers","mo":"phone"},"c":"Conrad and me and the last jumper. I miss the arguments. DON'T TELL ANYONE.","by":"sandy","n":"The quietest photo Sandy has ever appeared in."},{"id":"museum-family-12","y":2012,"t":"Opening Day","oc":"museum opening","w":["floyd","winnie","augusta","conrad","ram","rhoda","connie","emma","hiram"],"set":"studio","aw":"Floyd is in a cardboard museum case, Hiram is a face in the skylight above the group, Emma holds a four-page glossary, and Connie is checking her free kilobytes.","fx":["flash","tilt"],"m":{"floyd":"love","hiram":"wink","emma":"wow"},"h":{"emma":"clipboard","connie":"clipboard","floyd":"floppy"},"c":"Opening day. 2012. Everyone is here, and everyone is labeled. There's always room.","by":"connie","n":"The family finishes the album the way it started, with Floyd at the edge of the frame."},{"id":"museum-friends-12","y":2012,"t":"Friends, Pets and One Nameplate","oc":"museum opening","w":["dot","viv","sandy","mo","zack","tess","nibble","mat","toner"],"set":"studio","aw":"Tess's nameplate is on the wall behind them with 'LEASE' scribbled on it, Mat's cable is tangled with Toner's tail, Nibble has not aged, and Zack is still folded small.","fx":["photobomb","flash"],"m":{"tess":"love","nibble":"wow","toner":"wow","mat":"oops"},"h":{"dot":"flag","viv":"camera"},"c":"The friends and the pets. (and Tess.) (and Tess's nameplate.)","by":"dot","n":"Nobody is invited and everybody is here, which is how the family has always worked."}],"threads":[{"t":"Connie: From Walls to Open Rooms","w":["connie"],"b":[[1981,"Born the day the PC was announced and certain 640K is the whole world."],[1985,"Emma arrives with a bigger floor plan and Connie learns that sharing a house is mostly about doors."],[1991,"DOS 5 gives her room to stretch, and an empty living room feels a little spooky."],[1995,"Windows 95 takes the walls down and she is happy for everyone and misses them."],[2012,"Hosts the museum and teaches visitors to love the small rooms."]]},{"t":"Emma: From Page Frames to Footnotes","w":["emma"],"b":[[1985,"Born the year of the 386 and begins explaining before she can walk."],[1990,"Teaches Toner to sit in four points and one footnote."],[1993,"Doom climbs out of the house on a DOS extender and she is thrilled and a little jealous."],[1998,"Finds a fellow pedant in Mo and loses the baud argument by agreeing."],[2012,"Meets her 64-bit cousins and admits that even she does not need a footnote."]]},{"t":"Hiram: The Long Way Down","w":["hiram"],"b":[[1988,"Moves into the loft the same week he is born and calls it a promotion."],[1991,"DOS=HIGH sends the heavy furniture upstairs and he feels useful for the first time."],[1995,"Windows 95 makes the loft less special, and he stays anyway."],[2008,"Takes the pool slide instead of the stairs and says that does not count."],[2012,"Still on the high floor, now with Wi-Fi and a better basket."]]},{"t":"Ram: Plenty, Then Proud to Be Wrong","w":["ram"],"b":[[1981,"Declares 640K plenty, to cheers, and is correct."],[1991,"Reads the DOS 5 manual cover to cover and rearranges the furniture with a straight face."],[1995,"Holds the power strip while Rhoda's BIOS is flashed on a holiday."],[1999,"Stays up for Y2K with a flashlight and a clipboard and is, once again, right."],[2012,"Retires from nights, keeps the hours, and owns a very good thermos."]]},{"t":"Rhoda: The Rules Get a Clause","w":["rhoda"],"b":[[1981,"The PC arrives with Cassette BASIC in ROM, and Rhoda gets a room built for her."],[1988,"Hiram moves into the loft and she accepts it, in writing."],[1995,"Her BIOS goes flash and she accepts a careful rewrite on holidays."],[2002,"Lets Hiram attend the anniversary dinner by basket and calls it an amendment."],[2012,"Keeps the family rules and adds one: you may always ask."]]},{"t":"Floyd: The Story Gets Longer","w":["floyd"],"b":[[1981,"Brings 160K to the new PC and a story to go with it."],[1987,"Trades the floppy sleeve for a hard shell, which no longer fits his shirt pocket."],[1991,"Counts marshmallows as disks at the campsite and starts over when interrupted."],[1998,"Quietly sits with Zack after the click and tells him about disk 7."],[2012,"Retires to a cardboard museum case and tells his stories to anyone patient enough."]]},{"t":"Sandy and Conrad: The Quiet Alliance","w":["sandy","conrad"],"b":[[1989,"Sandy arrives and Conrad sighs for the first of many times."],[1992,"The 16-bit upgrade makes her very loud and very clear."],[1995,"Plug and play ends the IRQ fights, and both of them miss the arguments."],[2010,"They share the last jumper on the couch and do not discuss it."],[2012,"She stays on IRQ 5 out of loyalty and he tapes the chart to the wall."]]},{"t":"Dot Versus the Laser","w":["dot","toner"],"b":[[1981,"Born the same year as Connie and louder from day one."],[1985,"Gets 24 pins and a handwriting that looks professional."],[1986,"Meets Toner and does not yet know he will sit on a laser one day."],[1993,"Meets her first quiet laser printer and shrugs and prints more loudly."],[2012,"Prints for the museum, still in triplicate, still loud, with Toner signing the banners."]]},{"t":"Tess: Only a Minute","w":["tess"],"b":[[1983,"Knocks on the door and promises she will only be a minute."],[1984,"Pop-up utilities make hotkey TSRs famous, and she briefly feels like a star."],[1991,"LOADHIGH offers her a room upstairs and she politely declines."],[1999,"Gets a thank-you at Y2K for her tiny birthday cards."],[2012,"Still resident, now with a nameplate in the hallway that she calls a lease."]]},{"t":"The Pets: A Very Quiet Peace","w":["nibble","mat","toner"],"b":[[1982,"Nibble arrives as half a byte and twice the personality."],[1984,"Mat joins and Nibble respectfully ignores him."],[1986,"Toner arrives, sure he is a puppy."],[1996,"Mat sees a scroll wheel and pretends not to be impressed, and Nibble pretends not to be impressed that he pretends."],[2012,"All three sit within an inch of each other and refuse to admit it."]]}]};
